-- V103__Reload_All_Missing_Traffic_Signs.sql
-- Re-seeds all traffic sign categories that were cleared by V51-V61 migrations.
-- Only inserts signs NOT in E category (already seeded by V90).
-- Source: data/signs.json (260 signs, 260 of which 152 are non-E).

-- Step 1: Ensure category A exists
INSERT INTO categories (code, name_en, name_nl, name_fr, name_ar, description_en, display_order, is_active, created_at, updated_at)
VALUES ('A', 'Danger Signs', 'Gevaar', 'Danger', 'علامات الخطر', 'Warning signs indicating road hazards', 1, TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE name_en=VALUES(name_en), updated_at=NOW();

-- Step 2: Insert all non-E signs (A,B,C,D,F,G,H,M,Z)
INSERT INTO traffic_signs (category_id, sign_code, name_nl, name_en, name_fr, name_ar, description_nl, description_en, description_fr, description_ar, long_description_nl, long_description_en, long_description_fr, long_description_ar, image_url, is_active, created_at, updated_at)
VALUES    ((SELECT id FROM categories WHERE code='A'), 'A1a', 'Gevaarlijke bocht naar links', 'Dangerous curve to the left', 'Virage dangereux à gauche', 'منعطف خطير إلى اليسار', 'Waarschuwing voor een gevaarlijke bocht, eerst naar links.', 'Dangerous bend to the left.', 'Virage dangereux à gauche.', 'منعطف خطير إلى اليسار.', 'Waarschuwing voor een gevaarlijke bocht naar links op ongeveer 150 meter afstand. Verminder uw snelheid en let goed op.', 'Warning for a dangerous curve to the left at approximately 150 meters. Reduce your speed and pay attention.', 'Avertissement d''un virage dangereux à gauche à environ 150 mètres. Réduisez votre vitesse et soyez attentif.', 'تحذير من منعطف خطير إلى اليسار على مسافة 150 متر تقريباً. خفف من سرعتك وانتبه.', 'images/signs/danger_signs/A1a Gevaarlijke bocht naar rechts.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A1b', 'Gevaarlijke bocht naar rechts', 'Dangerous curve to the right', 'Virage dangereux à droite', 'منعطف خطير إلى اليمين', 'Waarschuwing voor een gevaarlijke bocht, eerst naar rechts.', 'Dangerous bend to the right.', 'Virage dangereux à droite.', 'منعطف خطير إلى اليمين.', 'Waarschuwing voor een gevaarlijke bocht naar rechts op ongeveer 150 meter afstand. Verminder uw snelheid en let goed op.', 'Warning for a dangerous curve to the right at approximately 150 meters. Reduce your speed and pay attention.', 'Avertissement d''un virage dangereux à droite à environ 150 mètres. Réduisez votre vitesse et soyez attentif.', 'تحذير من منعطف خطير إلى اليمين على مسافة 150 متر تقريباً. خفف من سرعتك وانتبه.', 'images/signs/danger_signs/A1b Gevaarlijke bocht naar rechts.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A1c', 'Gevaarlijke dubbele bocht (links-rechts)', 'Dangerous double curve (left-right)', 'Double virage dangereux (gauche-droite)', 'منعطف مزدوج خطير، الأول إلى اليسار', 'Waarschuwing voor een reeks gevaarlijke bochten, eerst naar links.', 'Dangerous bend. Double bend or succession of more than two bends, the first to the left.', 'Virage dangereux. Double virage ou succession de plus de deux virages, le premier à gauche.', 'منعطف خطر. الانحناء المزدوج أو تتابع أكثر من انحناءتين، الأولى إلى اليسار.', 'Waarschuwing voor een gevaarlijke dubbele bocht, de eerste naar links. Verminder uw snelheid en wees voorbereid op meerdere bochten.', 'Warning for a dangerous double curve, the first to the left. Reduce your speed and be prepared for multiple curves.', 'Avertissement d''un double virage dangereux, le premier à gauche. Réduisez votre vitesse et préparez-vous à plusieurs virages.', 'تحذير من منعطف مزدوج خطير، الأول على اليسار. قلل من سرعتك وكن مستعدًا لمنعطفات متعددة.', 'images/signs/danger_signs/A1c Gevaarlijke dubbele bocht (rechts-links).png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A1d', 'Gevaarlijke dubbele bocht (rechts-links)', 'Dangerous double curve (right-left)', 'Double virage dangereux (droite-gauche)', 'منعطف مزدوج خطير، الأول إلى اليمين', 'Waarschuwing voor een reeks gevaarlijke bochten, eerst naar rechts.', 'Dangerous bend. Double bend or succession of more than two bends, the first to the right.', 'Virage dangereux. Double virage ou succession de plus de deux virages, le premier à droite.', 'منعطف خطر. الانحناء المزدوج أو تتابع أكثر من ثنيتين، الأولى إلى اليمين.', 'Waarschuwing voor een gevaarlijke dubbele bocht, de eerste naar rechts. Verminder uw snelheid en wees voorbereid op meerdere bochten.', 'Warning for a dangerous double curve, the first to the right. Reduce your speed and be prepared for multiple curves.', 'Avertissement d''un double virage dangereux, le premier à droite. Réduisez votre vitesse et préparez-vous à plusieurs virages.', 'تحذير من منعطف مزدوج خطير، الأول على اليمين. قلل من سرعتك وكن مستعدًا لمنعطفات متعددة.', 'images/signs/danger_signs/A1d Gevaarlijke dubbele of meer dan twee bochten, de eerste naar rechts.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A3', 'Gevaarlijke daling', 'Dangerous descent', 'Descente dangereuse', 'خطر منحدر', 'Waarschuwing voor een gevaarlijke daling.', 'Dangerous descent.', 'Descente dangereuse.', 'نزول خطير.', 'Dit bord waarschuwt voor een gevaarlijke daling op de weg. Verminder voorzichtig uw snelheid en behoud de controle over het voertuig om slippen of verlies van controle te voorkomen.', 'This sign warns of a dangerous descent on the road. Carefully reduce your speed and maintain control of the vehicle to avoid skidding or losing control.', 'Ce panneau avertit d''une descente dangereuse sur la route. Réduisez prudemment votre vitesse et gardez le contrôle du véhicule pour éviter de déraper ou de perdre le contrôle.', 'تحذر هذه العلامة من منحدر خطير على الطريق. قلل سرعتك بعناية وحافظ على سيطرتك على السيارة لتجنب الانزلاق أو فقدان السيطرة.', 'images/signs/danger_signs/A3 Gevaarlijke daling.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A5', 'Gevaarlijke helling', 'Dangerous incline', 'Pente dangereuse', 'منحدر خطير', 'Waarschuwing voor een gevaarlijke helling.', 'Steep incline.', 'Montée raide.', 'صعود حاد.', 'Dit bord waarschuwt voor een gevaarlijke helling of hoogteverschil op de weg, zoals een verkeersdrempel of verhoogde brug. Verminder altijd uw snelheid en rijd voorzichtig om ongelukken te voorkomen.', 'This sign warns of a dangerous incline or elevation on the road, such as a speed bump or raised bridge. Always reduce your speed and drive carefully to avoid accidents.', 'Ce panneau avertit d''une pente dangereuse ou d''une élévation sur la route, comme un ralentisseur ou un pont surélevé. Réduisez toujours votre vitesse et conduisez prudemment pour éviter les accidents.', 'تحذر هذه العلامة من وجود منحدر أو ارتفاع خطير على الطريق، مثل مطب السرعة أو الجسر المرتفع. قم دائمًا بتقليل السرعة والقيادة بحذر لتجنب وقوع الحوادث.', 'images/signs/danger_signs/A5 Steile helling.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A7a', 'Versmalling langs beide zijden', 'Road narrows on both sides', 'Rétrécissement des deux côtés', 'تضيق الطريق من الجهتين', 'Rijbaanversmalling.', 'Road narrowing.', 'Rétrécissement de la chaussée.', 'تضييق الطريق.', 'Dit bord waarschuwt dat de weg smaller wordt aan beide zijden, door wegwerkzaamheden of een natuurlijke versmalling. Het is het beste om uw snelheid te verminderen en op te letten voor voertuigen uit de tegenovergestelde richting.', 'This sign warns that the road narrows on both sides, due to maintenance work or a natural narrowing. It is best to reduce your speed and watch out for vehicles coming from the opposite direction.', 'Ce panneau avertit que la route se rétrécit des deux côtés, en raison de travaux d''entretien ou d''un rétrécissement naturel. Il est préférable de réduire votre vitesse et de faire attention aux véhicules venant de la direction opposée.', 'تحذر هذه الشاخصة من أن الطريق يضيق من الجانبين بسبب أعمال الصيانة أو الضيق الطبيعي. ومن الأفضل أن تقلل من سرعتك وأن تنتبه للمركبات القادمة من الاتجاه المعاكس.', 'images/signs/danger_signs/A7a Rijbaanversmalling.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A7b', 'Versmalling langs links', 'Road narrows on the left', 'Rétrécissement à gauche', 'تضيق الطريق من جهة اليسار', 'Rijbaanversmalling langs links.', 'Road narrowing on the left.', 'Rétrécissement de la chaussée à gauche.', 'تضييق الطريق على اليسار.', 'De weg wordt smaller aan de linkerkant, wat de rijruimte voor voertuigen vermindert, door wegwerkzaamheden of de aard van de weg. Wij adviseren u om uw snelheid te verminderen, op het verkeer te letten en op de veilige rijstrook te blijven.', 'The road narrows on the left side, reducing the driving space for vehicles, due to maintenance work or the nature of the road. We advise you to reduce your speed, pay attention to traffic, and stay in the safe lane.', 'La route se rétrécit du côté gauche, réduisant l''espace de circulation pour les véhicules, en raison de travaux d''entretien ou de la nature de la route. Nous vous conseillons de réduire votre vitesse, de faire attention à la circulation et de rester dans la voie sûre.', 'يضيق الطريق من جهة اليسار مما يقلل المساحة المخصصة لقيادة المركبات بسبب أعمال الصيانة أو طبيعة الطريق. ننصحك بتخفيف السرعة، والانتباه لحركة المرور، والبقاء في المسار الآمن.', 'images/signs/danger_signs/A7b Versmalling langs rechts.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A7c', 'Versmalling langs rechts', 'Road narrows on the right', 'Rétrécissement à droite', 'تضيق الطريق من جهة اليمين', 'Rijbaanversmalling langs rechts.', 'Road narrowing on the right.', 'Rétrécissement de la chaussée à droite.', 'تضييق الطريق على اليمين.', 'De weg wordt smaller aan de rechterkant, wat de rijruimte voor voertuigen vermindert, mogelijk door wegwerkzaamheden of de aard van de weg. Wij adviseren u om uw snelheid te verminderen, op het verkeer te letten en op de veilige rijstrook te blijven.', 'The road narrows on the right side, reducing the driving space for vehicles, possibly due to maintenance work or the nature of the road. We advise you to reduce your speed, pay attention to traffic, and stay in the safe lane.', 'La route se rétrécit du côté droit, réduisant l''espace de circulation pour les véhicules, peut-être en raison de travaux d''entretien ou de la nature de la route. Nous vous conseillons de réduire votre vitesse, de faire attention à la circulation et de rester dans la voie sûre.', 'يضيق الطريق من جهة اليمين، مما يقلل من المساحة المخصصة لقيادة المركبات، ربما بسبب أعمال الصيانة أو طبيعة الطريق. ننصحك بتخفيف السرعة، والانتباه لحركة المرور، والبقاء في المسار الآمن.', 'images/signs/danger_signs/A7c Rijbaanversmalling langs rechts.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A11', 'Uitweg op een kaai of oever', 'Exit to a quay or riverbank', 'Sortie sur un quai ou une rive', 'الخروج إلى الرصيف أو ضفة النهر', 'Uitweg op een kaai of een oever.', 'Exit onto a quay or riverbank.', 'Débouché sur un quai ou une berge.', 'اخرج إلى الرصيف أو ضفة النهر.', 'Waarschuwing voor een uitweg naar een kaai of oever zonder bescherming. Gevaar om in het water te rijden. Verminder uw snelheid en let goed op.', 'Warning for an exit to a quay or riverbank without protection. Danger of driving into the water. Reduce your speed and pay attention.', 'Avertissement d''une sortie sur un quai ou une rive sans protection. Danger de tomber dans l''eau. Réduisez votre vitesse et soyez attentif.', 'تحذير بشأن الخروج إلى الرصيف أو ضفة النهر دون حماية. خطر القيادة في الماء. خفف من سرعتك وانتبه.', 'images/signs/danger_signs/A11 Slecht wegdek (oneffenheden).png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A13', 'Dwarse uitholling of ezelsrug', 'Speed bump or uneven road', 'Dos d''âne ou cassis', 'ظهر الجمل', 'Uitholling overdwars of ezelsrug.', 'Bump or dip in the road.', 'Cassis ou dos d''âne.', 'عثرة أو تراجع في الطريق.', 'Dit bord waarschuwt voor een verkeersdrempel of oneffenheden op de weg. Het geeft aan dat u uw snelheid moet verminderen om schade aan het voertuig te voorkomen en veilig te rijden. De aanbevolen snelheid is 30 km/u.', 'This sign warns of a speed bump or undulations on the road. It indicates the need to reduce speed to avoid damage to the vehicle and ensure safe driving. The recommended speed is 30 km/h.', 'Ce panneau avertit de la présence d''un dos d''âne ou d''ondulations sur la route. Il indique la nécessité de réduire la vitesse pour éviter d''endommager le véhicule et assurer une conduite en toute sécurité. La vitesse recommandée est de 30 km/h.', 'تحذر هذه العلامة من وجود مطب أو تموجات في السرعة على الطريق. ويشير إلى ضرورة تقليل السرعة لتجنب تلف السيارة وضمان القيادة الآمنة. السرعة الموصى بها هي 30 كم/ساعة.', 'images/signs/danger_signs/A13 Dwarse uitholling of ezelsrug.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A14', 'Verhoogde inrichting', 'Speed bump', 'Ralentisseur', 'مطب صناعي', 'Verhoogde inrichting.', 'Speed bump.', 'Ralentisseur.', 'مطب صناعي.', 'Dit bord geeft aan dat er een verkeersdrempel op de weg is om bestuurders te dwingen hun snelheid te verminderen. Deze bevinden zich altijd in woonwijken of in de buurt van scholen. De belangrijkste functie is het verlagen van de snelheid en het beschermen van voetgangers. Inhalen is hier verboden.', 'This sign indicates the presence of a speed bump on the road to force drivers to reduce their speed. It is always located in residential areas or near schools. Its main role is to reduce speed and protect pedestrians. Overtaking is prohibited here.', 'Ce panneau indique la présence d''un ralentisseur sur la route pour obliger les conducteurs à réduire leur vitesse. Il est toujours situé dans les zones résidentielles ou à proximité des écoles. Son rôle principal est de réduire la vitesse et de protéger les piétons. Le dépassement y est interdit.', 'تشير هذه العلامة إلى وجود مطب للسرعة على الطريق لإجبار السائقين على تخفيف السرعة. يقع دائمًا في المناطق السكنية أو بالقرب من المدارس. ويتمثل دورها الرئيسي في تقليل السرعة وحماية المشاة. التجاوز محظور هنا.', 'images/signs/danger_signs/A14 Verhoogde inrichting.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A15', 'Slipgevaar', 'Slippery road', 'Chaussée glissante', 'طريق زلق', 'Glibberige rijbaan.', 'Slippery road.', 'Chaussée glissante.', 'طريق زلق.', 'Dit bord waarschuwt bestuurders dat de weg glad kan zijn door regen, ijs of olie, wat vereist dat u uw snelheid vermindert en voorzichtig rijdt om verlies van controle over de auto te voorkomen.', 'This sign warns drivers that the road may be slippery due to rain, ice, or oil, which requires reducing speed and exercising caution to avoid losing control of the car.', 'Ce panneau avertit les conducteurs que la route peut être glissante en raison de la pluie, du verglas ou de l''huile, ce qui nécessite de réduire la vitesse et de faire preuve de prudence pour éviter de perdre le contrôle de la voiture.', 'تحذر هذه الإشارة السائقين من أن الطريق قد يكون زلقاً بسبب المطر أو الجليد أو الزيت، الأمر الذي يتطلب تخفيف السرعة وأخذ الحيطة والحذر لتجنب فقدان السيطرة على السيارة.', 'images/signs/danger_signs/A15 Slipgevaar - glad wegdek.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A17', 'Losliggende steenslag', 'Loose gravel', 'Gravillons', 'تطاير الحصى', 'Kiezelprojectie.', 'Gravel projection.', 'Projection de gravillons.', 'تناثر الحصى.', 'Dit bord waarschuwt voor losliggende steenslag op de weg, wat schade aan de voorruit kan veroorzaken of verlies van controle over het voertuig. Verminder uw snelheid en houd voldoende veiligheidsafstand.', 'This sign warns of loose gravel on the road, which may cause damage to the windshield or loss of control. Reduce your speed and maintain a safe distance.', 'Ce panneau avertit de la présence de gravillons sur la route, ce qui peut causer des dommages au pare-brise ou une perte de contrôle. Réduisez votre vitesse et maintenez une distance de sécurité.', 'تحذر هذه العلامة من وجود حصى غير متماسك على الطريق، مما قد يؤدي إلى تلف الزجاج الأمامي أو فقدان السيطرة. خفف سرعتك وحافظ على مسافة آمنة.', 'images/signs/danger_signs/A17 Zijdelingse wind.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A19', 'Vallende stenen', 'Falling rocks', 'Chutes de pierres', 'تساقط الأحجار', 'Vallende stenen.', 'Falling rocks.', 'Chute de pierres.', 'سقوط صخور.', 'Let op! Gevaar voor vallende rotsen in bergachtige gebieden. Verminder uw snelheid en vermijd stoppen in de buurt van hellingen.', 'Attention! Danger of falling rocks in mountainous areas. Reduce your speed and avoid stopping near slopes.', 'Attention! Danger de chutes de rochers dans les zones montagneuses. Réduisez votre vitesse et évitez de vous arrêter près des pentes.', 'انتباه! خطر تساقط الصخور في المناطق الجبلية. خفف من سرعتك وتجنب التوقف بالقرب من المنحدرات.', 'images/signs/danger_signs/A19 Vallende stenen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A21', 'Overstekende voetgangers', 'Pedestrian crossing', 'Passage pour piétons', 'منطقة عبور المشاة', 'Oversteekplaats voor voetgangers.', 'Pedestrian crossing.', 'Passage pour piétons.', 'ممر للمشاة.', 'Let op, de weg is bestemd voor of bevat een voetgangersoversteekplaats. Bij het zien van dit bord moet de bestuurder de snelheid verminderen en indien nodig stoppen om voetgangers veilig te laten oversteken.', 'Attention, the road is designated for or contains a pedestrian crossing. When seeing this sign, the driver must reduce speed and stop if necessary to allow pedestrians to cross safely.', 'Attention, la route est désignée pour ou contient un passage pour piétons. À la vue de ce panneau, le conducteur doit réduire sa vitesse et s''arrêter si nécessaire pour permettre aux piétons de traverser en toute sécurité.', 'انتبه، الطريق مخصص أو يحتوي على معبر للمشاة. عند رؤية هذه العلامة يجب على السائق تقليل السرعة والتوقف إذا لزم الأمر للسماح للمشاة بالعبور بأمان.', 'images/signs/danger_signs/A21 Overstekende voetgangers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A23', 'Kinderen', 'School crossing', 'Enfants', 'منطقة عبور مدارس', 'Plaats waar speciaal veel kinderen komen.', 'Area frequented by children.', 'Endroit fréquenté par des enfants.', 'المنطقة التي يرتادها الأطفال.', 'Bij het zien van dit bord, verminder uw snelheid tot 30 km/u en wees bereid te stoppen om kinderen en voetgangers te beschermen.', 'When seeing this sign, reduce your speed to 30 km/h and be prepared to stop to protect children and pedestrians.', 'À la vue de ce panneau, réduisez votre vitesse à 30 km/h et soyez prêt à vous arrêter pour protéger les enfants et les piétons.', 'عند رؤية هذه العلامة، خفف السرعة إلى 30 كم/ساعة وكن مستعداً للتوقف لحماية الأطفال والمشاة.', 'images/signs/danger_signs/A23 Kinderen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A25', 'Overstekende fietsers', 'Bicycle crossing', 'Traversée de cyclistes', 'منطقة عبور الدراجات', 'Oversteekplaats voor fietsers.', 'Cyclist crossing.', 'Passage pour cyclistes.', 'ممر لراكبي الدراجات.', 'Dit bord betekent dat de weg een oversteekplaats voor fietsers bevat. Bij het zien van dit bord moeten bestuurders hun snelheid verminderen, opletten bij kruispunten en fietsers voorrang geven om veilig over te steken.', 'This sign means that the road contains a crossing designated for cyclists. When seeing this sign, drivers must reduce speed, pay attention at intersections, and give cyclists priority to cross safely.', 'Ce panneau signifie que la route contient un passage réservé aux cyclistes. À la vue de ce panneau, les conducteurs doivent réduire leur vitesse, faire attention aux intersections et donner la priorité aux cyclistes pour traverser en toute sécurité.', 'هذه الإشارة تعني أن الطريق يحتوي على معبر مخصص لراكبي الدراجات الهوائية. عند رؤية هذه العلامة يجب على السائقين تقليل السرعة والانتباه عند التقاطعات وإعطاء راكبي الدراجات الأولوية للعبور بأمان.', 'images/signs/danger_signs/A25 Overstekende fietsers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A27', 'Overstekend groot wild', 'Wild animals crossing', 'Passage d''animaux sauvages', 'عبور الحيوانات البرية', 'Doortocht van groot wild.', 'Wild animals crossing.', 'Passage de gros gibier.', 'عبور حيوانات برية.', 'Dit bord waarschuwt voor de mogelijkheid dat grote dieren de weg oversteken, vooral in landelijke gebieden of bossen. Verminder daarom uw snelheid en let goed op om ongelukken te voorkomen.', 'This sign warns of the possibility of large animals crossing the road, especially in rural areas or forests. Therefore, reduce your speed and pay attention to avoid accidents.', 'Ce panneau avertit de la possibilité que de grands animaux traversent la route, en particulier dans les zones rurales ou les forêts. Réduisez donc votre vitesse et soyez attentif pour éviter les accidents.', 'تحذر هذه العلامة من احتمالية عبور الحيوانات الكبيرة للطريق، خاصة في المناطق الريفية أو الغابات. لذلك، خفف من سرعتك وانتبه لتفادي وقوع الحوادث.', 'images/signs/danger_signs/A27 Overstekend groot wild.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A29', 'Overstekend vee', 'Livestock crossing', 'Passage de bétail', 'عبور الماشية', 'Doortocht van vee.', 'Cattle crossing.', 'Passage de bétail.', 'عبور ماشية.', 'Dit bord waarschuwt voor de mogelijkheid dat grote dieren zoals koeien of schapen de weg oversteken, vooral in landelijke gebieden. Verminder uw snelheid en let goed op om ongelukken te voorkomen.', 'This sign warns of the possibility of large animals such as cows or sheep crossing the road, especially in rural areas. Reduce your speed and pay attention to avoid accidents.', 'Ce panneau avertit de la possibilité que de grands animaux comme des vaches ou des moutons traversent la route, en particulier dans les zones rurales. Réduisez votre vitesse et soyez attentif pour éviter les accidents.', 'تحذر هذه العلامة من احتمال عبور الحيوانات الكبيرة مثل الأبقار أو الأغنام الطريق، خاصة في المناطق الريفية. خفف من سرعتك وانتبه لتجنب الحوادث.', 'images/signs/danger_signs/A29 Overstekend vee.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A31', 'Werken', 'Roadworks', 'Travaux', 'أعمال على الطريق', 'Werken.', 'Roadworks.', 'Travaux.', 'أشغال على الطريق.', 'Dit bord geeft aan dat er wegwerkzaamheden plaatsvinden, wat vereist dat bestuurders hun snelheid verminderen, de oranje wegwijzers volgen en opletten voor mogelijke aanwezigheid van arbeiders of apparatuur in het gebied.', 'This sign indicates the presence of road maintenance work, which requires drivers to reduce speed, follow the orange directional signs on the road, and pay attention to the possible presence of workers or equipment in the area.', 'Ce panneau indique la présence de travaux d''entretien routier, ce qui nécessite que les conducteurs réduisent leur vitesse, suivent les panneaux directionnels orange sur la route et fassent attention à la présence éventuelle d''ouvriers ou d''équipements dans la zone.', 'تشير هذه الشاخصة إلى وجود أعمال صيانة للطريق، مما يتطلب من السائقين تخفيف السرعة واتباع العلامات الإرشادية البرتقالية اللون على الطريق، والانتباه إلى احتمال تواجد عمال أو معدات في المنطقة.', 'images/signs/danger_signs/A31 Werken.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A33', 'Verkeerslichten', 'Traffic lights', 'Feux de signalisation', 'وجود إشارة ضوئية', 'Oversteekplaats voor ruiters.', NULL, NULL, NULL, 'Let op! Dit bord waarschuwt voor verkeerslichten verderop op de weg. U moet opletten en uw snelheid aanpassen aan de staat van het verkeerslicht, door te stoppen of door te rijden, om een veilige en vlotte verkeersstroom te garanderen.', 'Attention! This sign warns of traffic lights ahead on the road. You must pay attention and adjust your speed according to the traffic light status, whether stopping or continuing to drive, to ensure safe and smooth traffic flow.', 'Attention! Ce panneau avertit de la présence de feux de signalisation sur la route. Vous devez faire attention et adapter votre vitesse en fonction de l''état du feu, en vous arrêtant ou en continuant à conduire, pour assurer une circulation sûre et fluide.', 'انتباه! تحذر هذه العلامة من وجود إشارات مرور أمامك على الطريق. يجب عليك الانتباه وضبط سرعتك حسب حالة الإشارة الضوئية سواء التوقف أو الاستمرار في القيادة، لضمان انسيابية حركة المرور بشكل آمن وسلس.', 'images/signs/danger_signs/A33 Verkeerslichten.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A35', 'Laagvliegende vliegtuigen', 'Low-flying aircraft', 'Avions à basse altitude', 'طائرات تحلق على ارتفاع منخفض', 'Gevaarlijk kruispunt.', NULL, NULL, NULL, 'Dit bord geeft aan dat er mogelijk vliegtuigen op lage hoogte over de weg vliegen. Bestuurders wordt aangeraden niet te schrikken bij het horen of zien van vliegtuigen en voorzichtig en stabiel te blijven rijden.', 'This sign indicates that aircraft may fly at low altitude over the road. Drivers are advised not to be frightened when hearing or seeing aircraft, and to continue driving carefully and steadily.', 'Ce panneau indique que des avions peuvent voler à basse altitude au-dessus de la route. Il est conseillé aux conducteurs de ne pas avoir peur en entendant ou en voyant des avions et de continuer à conduire prudemment et de manière stable.', 'تشير هذه العلامة إلى أن الطائرة قد تطير على ارتفاع منخفض فوق الطريق. وينصح السائقون بعدم الخوف عند سماع أو رؤية الطائرات، ومواصلة القيادة بحذر وثبات.', 'images/signs/danger_signs/A35 Laagvliegende vliegtuigen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A37', 'Zijwind', 'Side wind', 'Vent latéral', 'وجود رياح جانبية', 'Zijwind.', 'Crosswind.', 'Vent latéral.', 'رياح جانبية.', 'Dit bord geeft aan dat er mogelijk sterke zijwind is die de stabiliteit van voertuigen kan beïnvloeden, vooral vrachtwagens en motorfietsen. Bij het zien van dit bord moet u uw snelheid verminderen, het stuur stevig vasthouden en alert zijn op mogelijke afwijking van het voertuig door de wind.', 'This sign indicates the possibility of strong side winds that may affect vehicle balance, especially trucks and motorcycles. When seeing this sign, you must reduce speed, hold the steering wheel firmly, and be alert to possible vehicle deviation due to the wind.', 'Ce panneau indique la possibilité de vents latéraux forts pouvant affecter l''équilibre des véhicules, en particulier les camions et les motos. À la vue de ce panneau, vous devez réduire votre vitesse, tenir fermement le volant et être attentif à une éventuelle déviation du véhicule due au vent.', 'تشير هذه الإشارة إلى احتمالية هبوب رياح جانبية قوية قد تؤثر على توازن المركبات وخاصة الشاحنات والدراجات النارية. عند رؤية هذه الإشارة عليك خفض السرعة والإمساك بالمقود بقوة والتنبه لاحتمال انحراف السيارة بسبب الرياح.', 'images/signs/danger_signs/A37 Zijwind.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A39', 'Tweerichtingsverkeer', 'Two-way traffic', 'Circulation à double sens', 'بداية طريق باتجاهين', 'Verkeer toegelaten in twee richtingen na een gedeelte van de rijbaan met eenrichtingsverkeer.', 'Two-way traffic after one-way section.', 'Circulation à double sens après une section à sens unique.', 'حركة المرور في اتجاهين بعد قسم في اتجاه واحد.', 'Dit bord waarschuwt voor het begin van tweerichtingsverkeer na een stuk eenrichtingsverkeer, wat betekent dat voertuigen uit de tegenovergestelde richting plotseling kunnen verschijnen. Daarom moeten bestuurders voorzichtig zijn.', 'This sign alerts us to the start of a two-way road after a one-way road, meaning vehicles coming from the opposite direction may appear suddenly. Therefore, drivers must exercise caution.', 'Ce panneau nous avertit du début d''une route à double sens après une route à sens unique, ce qui signifie que des véhicules venant de la direction opposée peuvent apparaître soudainement. Les conducteurs doivent donc faire preuve de prudence.', 'تنبهنا هذه الإشارة إلى بدء طريق ذو اتجاهين بعد طريق ذو اتجاه واحد، مما يعني أن المركبات القادمة من الاتجاه المعاكس قد تظهر فجأة. ولذلك يجب على السائقين توخي الحذر.', 'images/signs/danger_signs/A39 Twee richtingsverkeer toegelaten na een stuk éénrichtingsverkeer.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A41', 'Overweg met slagbomen', 'Railway crossing with barriers', 'Passage à niveau avec barrières', 'تقاطع سكة حديدية مزود بحاجز', 'Overweg met slagbomen.', 'Level crossing with barriers.', 'Passage à niveau avec barrières.', 'معبر سكة حديد بحواجز.', 'Dit bord geeft aan dat er een spoorwegovergang is met een slagboom die sluit wanneer er een trein passeert. Bestuurders moeten stoppen wanneer ze de waarschuwingssirene horen en indien nodig de motor van de auto uitschakelen.', 'This sign indicates the presence of a railway crossing equipped with a barrier that closes when a train passes. Drivers must stop when hearing the warning siren and turn off the car engine if necessary.', 'Ce panneau indique la présence d''un passage à niveau équipé d''une barrière qui se ferme lors du passage d''un train. Les conducteurs doivent s''arrêter en entendant la sirène d''avertissement et couper le moteur si nécessaire.', 'تشير هذه الإشارة إلى وجود معبر للسكك الحديدية مزود بحاجز يغلق عند مرور القطار. ويجب على السائقين التوقف عند سماع صفارة الإنذار وإطفاء محرك السيارة إذا لزم الأمر.', 'images/signs/danger_signs/A41 Overweg met slagbomen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A43', 'Overweg zonder slagbomen', 'Railway crossing without barriers', 'Passage à niveau sans barrières', 'معبر قطار بدون حاجز', 'Overweg zonder slagbomen.', 'Level crossing without barriers.', 'Passage à niveau sans barrières.', 'معبر سكة حديد بدون حواجز.', 'Dit bord waarschuwt voor een spoorwegovergang zonder slagbomen, wat vereist dat u stopt en controleert of de spoorlijn vrij is voordat u oversteekt om ongelukken te voorkomen. Inhalen is op deze weg verboden.', 'This sign warns of a railway crossing without barriers, which requires stopping and making sure the track is clear before crossing to avoid accidents. Overtaking is prohibited on this road.', 'Ce panneau avertit d''un passage à niveau sans barrières, ce qui nécessite de s''arrêter et de s''assurer que la voie est libre avant de traverser pour éviter les accidents. Le dépassement est interdit sur cette route.', 'تحذر هذه الشاخصة من عبور السكة الحديد بدون حواجز، مما يتطلب التوقف والتأكد من خلو المسار قبل العبور لتجنب الحوادث. التجاوز ممنوع على هذا الطريق.', 'images/signs/danger_signs/A43 Overweg zonder slagbomen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A45', 'Waarschuwingskruis', 'Warning cross', 'Croix d''avertissement', 'صليب تحذير', 'Overweg voor enkel spoor.', 'Single track railway crossing.', 'Passage à niveau à voie unique.', 'معبر سكة حديد ذو خط واحد.', 'Waarschuwing voor een spoorwegovergang. Stop voor de spoorwegovergang als de lichten knipperen.', 'Warning for a railway crossing ahead. Stop at the railway crossing if lights are flashing.', 'Avertissement d''un passage à niveau. Arrêtez-vous au passage à niveau si les feux clignotent.', 'تحذير من وجود معبر للسكك الحديدية أمامك. توقف عند معبر السكة الحديد إذا كانت الأضواء تومض.', 'images/signs/danger_signs/A45 waarschuwingskruis.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A47', 'Waarschuwingskruis meerdere sporen', 'Multi-track warning cross', 'Croix d''avertissement multipiste', 'تقاطع تحذيري متعدد المسارات', 'Overweg voor twee of meer sporen.', 'Multi-track railway crossing.', 'Passage à niveau à plusieurs voies.', 'معبر سكة حديد متعدد الخطوط.', 'Waarschuwing voor een spoorwegovergang. Stop voor de spoorwegovergang als de lichten knipperen.', 'Warning for a railway crossing ahead. Stop at the railway crossing if lights are flashing.', 'Avertissement d''un passage à niveau. Arrêtez-vous au passage à niveau si les feux clignotent.', 'تحذير من وجود معبر للسكك الحديدية أمامك. توقف عند معبر السكة الحديد إذا كانت الأضواء تومض.', 'images/signs/danger_signs/A47 waarschuwingskruis_meerdere_sporen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A49', 'Kruising met sporen', 'Crossing with tram or train tracks', 'Croisement avec voies de tram ou train', 'تقاطع طرق مع سكة ترام أو قطار', 'Kruising van een openbare weg door een of meer in de rijbaan aangelegde sporen.', 'Crossing with tram or train tracks in the road.', 'Croisement avec des voies de tram ou de train dans la chaussée.', 'العبور مع خطوط الترام أو القطار في الطريق.', 'Dit bord waarschuwt dat de weg kruist met geïntegreerde sporen van een tram of trein met meer dan één spoor. Bestuurders moeten voorzichtig zijn en voorrang geven aan het openbaar vervoer.', 'This sign warns that the road crosses with integrated tram or train tracks with more than one track. Drivers must be cautious and give priority to public transportation.', 'Ce panneau avertit que la route croise des voies intégrées de tramway ou de train avec plus d''une voie. Les conducteurs doivent être prudents et donner la priorité aux transports en commun.', 'تحذرنا هذه العلامة إلى أن الطريق يتقاطع مع مسارات مدمجة مع سكة ترام أو قطار بأكثر من مسار، ويجب على السائقين الحذر وإعطاء الأولوية للمواصلات العامة.', 'images/signs/danger_signs/A49 Kruising van een openbare weg door een of meer in de rijbaan aangelegde sporen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A50', 'Opgelet file', 'Traffic jam ahead', 'Attention embouteillage', 'ازدحام مروري', 'File.', NULL, NULL, NULL, 'Dit bord waarschuwt voor mogelijke file. Verminder uw snelheid en houd voldoende veiligheidsafstand om ongelukken te voorkomen.', 'This sign warns of possible traffic congestion. Reduce your speed and maintain a safe distance to avoid accidents.', 'Ce panneau avertit d''un embouteillage possible. Réduisez votre vitesse et gardez une distance de sécurité pour éviter les accidents.', 'تحذر هذه العلامة من احتمال حدوث ازدحام مروري. خفف من سرعتك وحافظ على مسافة آمنة لتجنب وقوع الحوادث.', 'images/signs/danger_signs/A50 Opgelet file.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A51', 'Algemeen gevaar', 'General danger', 'Danger général', 'خطر عام', 'Gevaar dat niet door een speciaal symbool wordt bepaald. Een onderbord duidt de aard van het gevaar aan.', 'Danger not specified by a special symbol. A sub-sign indicates the nature of the danger.', 'Danger non spécifié par un symbole spécial. Un panneau additionnel indique la nature du danger.', 'خطر غير محدد برمز خاص. علامة فرعية تشير إلى طبيعة الخطر.', 'Dit waarschuwingsbord attendeert bestuurders op een algemeen gevaar op de weg zonder een specifiek symbool. Er wordt vaak een extra bord onder geplaatst om de aard van het gevaar te verduidelijken, zoals een gladde weg of wegwerkzaamheden. Bij het zien van dit bord wordt aangeraden om uw snelheid te verminderen en extra alert te zijn, omdat het gevaar onverwacht kan zijn.', 'This warning sign alerts drivers to a general danger on the road without specifying it with a special symbol. An additional sign is often placed below to clarify the nature of the danger, such as a slippery road or roadworks. When seeing this sign, it is recommended to reduce your speed and increase attention because the danger may be unexpected.', 'Ce panneau d''avertissement alerte les conducteurs d''un danger général sur la route sans le spécifier par un symbole spécial. Un panneau supplémentaire est souvent placé en dessous pour clarifier la nature du danger, comme une route glissante ou des travaux routiers. À la vue de ce panneau, il est recommandé de réduire votre vitesse et d''augmenter votre attention car le danger peut être inattendu.', 'تنبه هذه العلامة التحذيرية السائقين إلى وجود خطر عام على الطريق دون تحديده برمز خاص. غالبًا ما يتم وضع علامة إضافية بالأسفل لتوضيح طبيعة الخطر، مثل طريق زلق أو أعمال الطرق. عند رؤية هذه العلامة ينصح بتقليل السرعة وزيادة الانتباه لأن الخطر قد يكون غير متوقع.', 'images/signs/danger_signs/A51 Gevaar dat niet door een speciaal symbool wordt bepaald.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='A'), 'A53', 'Opgelet verzinkbare paal', 'Retractable bollard', 'Attention borne escamotable', 'انتباه عمود قابل للسحب', NULL, NULL, NULL, NULL, 'Waarschuwingsbord: Opgelet verzinkbare paal Let op en pas uw snelheid aan.', 'Warning sign: danger ahead. Pay attention and adjust your speed.', 'Panneau d''avertissement : danger. Soyez attentif et adaptez votre vitesse.', 'علامة تحذير: خطر أمامك. انتبه واضبط سرعتك.', 'images/signs/danger_signs/A53 Verzinkbare paaltjes.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B1', 'Voorrang verlenen', 'Give way', 'Cédez le passage', 'إعطاء الأولوية', 'Verplichting om voorrang te verlenen aan bestuurders op de kruisende weg.', 'Give way.', 'Cédez le passage.', 'أعط الأولوية.', 'Dit bord (omgekeerde driehoek) geeft aan dat u moet stoppen of vertragen en de weg vrij moet maken voor voertuigen die van rechts of links komen op de hoofdweg bij kruispunten, en moet stoppen indien nodig.', 'This sign (inverted triangle) indicates the need to stop or slow down and give way to vehicles coming from the right or left on the main road at intersections, and stop if necessary.', 'Ce panneau (triangle inversé) indique la nécessité de s''arrêter ou de ralentir et de céder le passage aux véhicules venant de droite ou de gauche sur la route principale aux intersections, et de s''arrêter si nécessaire.', 'تشير هذه الإشارة (المثلث المقلوب) إلى ضرورة التوقف أو التخفيف من السرعة وإفساح المجال أمام المركبات القادمة من اليمين أو اليسار على الطريق الرئيسي عند التقاطعات، والتوقف إذا لزم الأمر.', 'images/signs/priority_signs/B1 Voorrang verlenen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B5', 'Stop en voorrang verlenen', 'Stop and give way', 'Arrêt et cédez le passage', 'توقف وأفسح المجال', 'Verplichting om volledig te stoppen en voorrang te verlenen.', 'Stop and give way.', 'Stop et cédez le passage.', 'توقف وأفسح المجال.', 'Dit bord verplicht u om volledig te stoppen en de weg vrij te maken voor voertuigen die van rechts en links komen op de hoofdweg bij kruispunten. U mag niet doorrijden voordat u zeker weet dat de weg vrij is.', 'This sign requires a mandatory stop and giving way to vehicles coming from the right and left on the main road at intersections. You may not continue driving until you are sure the road is clear.', 'Ce panneau impose un arrêt obligatoire et de céder le passage aux véhicules venant de droite et de gauche sur la route principale aux intersections. Vous ne pouvez pas continuer à conduire avant de vous assurer que la route est libre.', 'تشترط هذه الإشارة التوقف الإلزامي وإفساح المجال للمركبات القادمة من اليمين واليسار على الطريق الرئيسي عند التقاطعات. لا يجوز لك الاستمرار في القيادة حتى تتأكد من أن الطريق خالي.', 'images/signs/priority_signs/B5 Stop en voorrang verlenen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B9', 'Voorrangsweg', 'Priority road', 'Route prioritaire', 'طريق الأولوية', 'Aanduiding van een weg waarop de bestuurder voorrang heeft.', 'Priority road.', 'Route prioritaire.', 'طريق الأولوية.', 'Dit bord geeft aan dat u voorrang heeft vanaf het eerste kruispunt waar het verschijnt tot het bord einde voorrangsweg verschijnt. Voertuigen die van zijwegen komen moeten u de weg vrij maken. Dit bord wordt vaak geplaatst op wegen met een snelheid van 50 km/u of meer.', 'This sign indicates that you have priority from the first intersection where it appears until the end of priority road sign appears. Vehicles coming from side roads must give way to you. It is often placed on roads with a speed of 50 km/h or more.', 'Ce panneau indique que vous avez la priorité dès le premier carrefour où il apparaît jusqu''à l''apparition du panneau de fin de route prioritaire. Les véhicules venant des routes latérales doivent vous céder le passage. Il est souvent placé sur des routes avec une vitesse de 50 km/h ou plus.', 'تشير هذه الإشارة إلى أن لك الأولوية من أول تقاطع حيث تظهر حتى نهاية إشارة الطريق ذات الأولوية. يجب على المركبات القادمة من الطرق الجانبية أن تفسح المجال لك. غالبًا ما يتم وضعه على الطرق بسرعة 50 كم/ساعة أو أكثر.', 'images/signs/priority_signs/B9 Voorrangsweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B11', 'Einde voorrangsweg', 'End of priority road', 'Fin de route prioritaire', 'انتهاء طريق الأولوية', 'Geeft het einde aan van een voorrangsweg.', 'End of priority road.', 'Fin de route prioritaire.', 'نهاية طريق الأولوية.', 'Dit bord geeft het einde van de voorrangsweg aan, wat betekent dat bestuurders nu de gebruikelijke voorrangsregels op kruispunten moeten respecteren en voorrang moeten verlenen aan voertuigen die van rechts komen, of volgens de verkeersborden op de weg.', 'This sign indicates the end of the priority road, meaning drivers must now respect the usual priority rules at intersections and give way to vehicles coming from the right, or according to the traffic signs on the road.', 'Ce panneau indique la fin de la route prioritaire, ce qui signifie que les conducteurs doivent maintenant respecter les règles de priorité habituelles aux intersections et céder le passage aux véhicules venant de droite, ou selon les panneaux de signalisation sur la route.', 'تشير هذه العلامة إلى نهاية الطريق الرئيسي، مما يعني أنه يجب على السائقين الآن احترام قواعد الأولوية المعتادة عند التقاطعات وإفساح المجال للمركبات القادمة من اليمين، أو حسب إشارات المرور على الطريق.', 'images/signs/priority_signs/B11 Einde van voorrangsweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15a', 'Voorrang op de kruisende zijwegen.', 'Priority op de kruisende zijwegen.', 'Priorité op de kruisende zijwegen.', 'أولوية على الطرق الجانبية المتقاطعة', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Voorrangsbord: Voorrang op de kruisende zijwegen.. Volg de aangegeven voorrangsregels.', 'Priority sign: follow the indicated priority rules.', 'Panneau de priorité : suivez les règles de priorité indiquées.', 'علامة أولوية: اتبع قواعد الأولوية المحددة.', 'images/signs/priority_signs/B15a Voorrang op het eerstvolgende kruispunt - variant schuine zijweg links.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15b', 'Versmalling schuin rechts', 'B15a Variant diagonal right', 'B15a Variante diagonale droite', 'B15a البديل قطري اليمين', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Voorrangsbord: Voorrang op de kruisende zijwegen. Volg de aangegeven voorrangsregels.', 'Priority sign: follow the indicated priority rules.', 'Panneau de priorité : suivez les règles de priorité indiquées.', 'علامة أولوية: اتبع قواعد الأولوية المحددة.', 'images/signs/priority_signs/B15b Voorrang op het eerstvolgende kruispunt - variant schuine zijweg rechts.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15c', 'Voorrang op kruisende zijwegen', 'Priority over crossing side roads', 'Priorité sur les routes latérales', 'الأولوية على الطرق الجانبية المتقاطعة', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Dit bord geeft u voorrang op de weg en eindigt na het eerste kruispunt. Er is geen bord einde voorrang omdat het alleen geldt voor één straat of één kruispunt. Voertuigen die van rechts en links komen moeten u voorrang verlenen.', 'This sign gives you priority on the road and ends after the first intersection. There is no end of priority sign because it only applies to one street or one intersection. Vehicles coming from the right and left must give you the right of way.', 'Ce panneau vous donne la priorité sur la route et se termine après le premier carrefour. Il n''y a pas de panneau de fin de priorité car il ne s''applique qu''à une seule rue ou un seul carrefour. Les véhicules venant de droite et de gauche doivent vous céder le passage.', 'هذه العلامة تعطيك الأولوية على الطريق وتنتهي بعد التقاطع الأول. لا توجد إشارة نهاية للأولوية لأنها تنطبق على شارع واحد أو تقاطع واحد فقط. المركبات القادمة من اليمين واليسار يجب أن تعطيك حق الأولوية.', 'images/signs/priority_signs/B15c Voorrang op het eerstvolgende kruispunt.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15d', 'Voorrang op kruisende zijweg links', 'Priority over crossing side road on the left', 'Priorité sur la route latérale à gauche', 'الأولوية على الطريق الجانبي اليسار', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Dit bord betekent dat het voertuig dat op de hoofdweg rijdt voorrang heeft. Voertuigen die van rechts komen moeten stoppen of wachten tot de weg vrij is voordat ze verder rijden.', 'This sign means that the vehicle traveling on the main road has priority. Those coming from the right must stop or wait until the road is clear before proceeding.', 'Ce panneau signifie que le véhicule circulant sur la route principale a la priorité. Ceux venant de droite doivent s''arrêter ou attendre que la route soit libre avant de continuer.', 'تعني هذه الإشارة أن السيارة التي تسير على الطريق الرئيسي لها الأولوية. يجب على القادمين من اليمين التوقف أو الانتظار حتى يصبح الطريق خالياً قبل المواصلة.', 'images/signs/priority_signs/B15d Voorrang op het eerstvolgende kruispunt - variant zijweg links.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15e', 'Voorrang op linker zijweg', 'Priority over left side road', 'Priorité sur la route latérale à gauche', 'الأولوية على الطريق الجانبي اليسار', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Dit bord geeft voorrang aan bestuurders op de hoofdweg vanaf de linkerkant. Bestuurders die van de zijweg komen moeten stoppen of wachten tot de weg vrij is.', 'This sign gives priority to drivers on the main road from the left side. Drivers coming from the side road must stop or wait until the road is clear.', 'Ce panneau donne la priorité aux conducteurs sur la route principale du côté gauche. Les conducteurs venant de la route latérale doivent s''arrêter ou attendre que la route soit dégagée.', 'هذه العلامة تعطي الأولوية للسائقين على الطريق الرئيسي من الجانب الأيسر. يجب على السائقين القادمين من الطريق الجانبي التوقف أو الانتظار حتى يصبح الطريق خاليًا.', 'images/signs/priority_signs/B15e Voorrang op het eerstvolgende kruispunt - variant T-kruispunt.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15f', 'Voorrang op kruisende zijweg links', 'Priority over crossing side road on the left', 'Priorité sur la route latérale à gauche', 'الأولوية على الطريق الجانبي اليسار', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Dit bord geeft aan dat u op een hoofdweg rijdt met voorrang op alle voertuigen die van links komen. Bestuurders moeten wachten tot de bestuurder op de hoofdweg is gepasseerd.', 'This sign indicates that you are driving on a main road with priority over all vehicles coming from the left. Drivers must wait until the driver on the main road has passed.', 'Ce panneau indique que vous conduisez sur une route principale avec priorité sur tous les véhicules venant de gauche. Les conducteurs doivent attendre que le conducteur sur la route principale soit passé.', 'تشير هذه العلامة إلى أنك تقود على طريق رئيسي مع الأولوية على جميع المركبات القادمة من اليسار. يجب على السائقين الانتظار حتى مرور السائق على الطريق الرئيسي.', 'images/signs/priority_signs/B15f Voorrang op het eerstvolgende kruispunt - variant Y-kruispunt.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15g', 'Voorrang op kruisende zijweg', 'Priority over crossing side road', 'Priorité sur la route latérale de croisement', 'الأولوية على الطريق الجانبي اليمين', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Dit bord geeft aan dat u op een voorrangsweg rijdt en voorrang heeft op alle voertuigen die van rechts komen. Bestuurders moeten wachten tot de bestuurder op de hoofdweg is gepasseerd.', 'This sign indicates that you are driving on a priority road and have priority over all vehicles coming from the right. Drivers must wait until the driver on the main road has passed.', 'Ce panneau indique que vous circulez sur une route prioritaire et que vous avez la priorité sur tous les véhicules venant de la droite. Les conducteurs doivent attendre que le conducteur sur la route principale soit passé.', 'تشير هذه العلامة إلى أنك تقود على طريق رئيسي وأن لك الأولوية على جميع المركبات القادمة من اليمين. يجب على السائقين الانتظار حتى مرور السائق على الطريق الرئيسي.', 'images/signs/priority_signs/B15g Voorrang op kruisende zijweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B21', 'Voorrang op kruisende zijweg rechts', 'Priority over crossing side road on the right', 'Priorité sur la route latérale à droite', 'الأولوية على الطريق الجانبي اليمين', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Dit bord geeft u voorrang op de hoofdweg aan de rechterkant. Bestuurders die van rechts komen moeten stoppen en hebben meestal een bord voorrang verlenen.', 'This sign gives us priority on the main road from the right side. Drivers coming from the right must stop and usually have a give way sign.', 'Ce panneau nous donne la priorité sur la route principale du côté droit. Les conducteurs venant de droite doivent s''arrêter et ont généralement un panneau de cédez le passage.', 'هذه العلامة تعطينا الأولوية للطريق الرئيسي من الجانب الأيمن. يجب على السائقين القادمين من اليمين التوقف وعادةً ما تكون لديهم إشارة إفساح الطريق.', 'images/signs/priority_signs/B21 Smalle doorgang. Voorrang ten opzichte van de bestuurders die uit de tegenovergestelde richting komen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B15g', 'Voorrang op kruisende zijweg rechts', 'Priority over crossing side road on the right', 'Priorité sur la route latérale à droite', 'الأولوية على الطريق الجانبي اليمين', 'Voorrang. De horizontale streep van het symbool mag worden gewijzigd om duidelijker plaatsgesteldheid weer te geven.', 'Priority. The horizontal line may be modified to show local conditions.', 'Priorité. La ligne horizontale peut être modifiée pour montrer les conditions locales.', 'أولوية. يمكن تعديل الخط الأفقي لإظهار الظروف المحلية.', 'Dit bord betekent dat het voertuig dat op de hoofdweg rijdt voorrang heeft. Voertuigen die van links komen moeten stoppen of wachten tot de weg vrij is voordat ze verder rijden.', 'This sign means that the vehicle traveling on the main road has priority. Those coming from the left must stop or wait until the road is clear before proceeding.', 'Ce panneau signifie que le véhicule circulant sur la route principale a la priorité. Ceux venant de gauche doivent s''arrêter ou attendre que la route soit libre avant de continuer.', 'تعني هذه الإشارة أن السيارة التي تسير على الطريق الرئيسي لها الأولوية. ويجب على القادمين من اليسار التوقف أو الانتظار حتى يصبح الطريق خالياً قبل المواصلة.', 'images/signs/priority_signs/B15g Voorrang op kruisende zijweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B17', 'Voorrang van rechts', 'Priority to the right', 'Priorité à droite', 'إعطاء الأولوية لليمين', 'Voorrang van rechts.', 'Priority from the right.', 'Priorité à droite.', 'أولوية من اليمين.', 'Dit bord waarschuwt voor een kruispunt waar de regel van voorrang van rechts van toepassing is, wat betekent dat u volledig geen voorrang heeft binnen het kruispunt, zelfs als u op een hoofdweg rijdt.', 'This sign alerts to an intersection where the rule of giving priority to traffic from the right applies, meaning you have completely lost priority within the intersections, even if you are on a main road.', 'Ce panneau avertit d''un carrefour où la règle de priorité à droite s''applique, ce qui signifie que vous avez complètement perdu la priorité dans les intersections, même si vous êtes sur une route principale.', 'تنبهك هذه العلامة المرورية إلى وجود تقاطع تنطبق عليه قاعدة إعطاء الأولوية لحركة المرور من اليمين، مما يعني أنك فقدت الأولوية تمامًا داخل التقاطعات، حتى لو كنت على طريق رئيسي.', 'images/signs/priority_signs/B17 Kruispunt waar de voorrang van rechts geldt.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B19', 'Voorrang verlenen aan tegenliggers', 'Give way to oncoming traffic', 'Céder le passage aux véhicules venant en sens inverse', 'إفساح المجال لحركة المرور القادمة', 'Smalle doorgang. Gebod doorgang te verlenen aan de bestuurders die uit de tegenovergestelde richting komen.', 'Narrow passage. Obligation to give way to drivers from the opposite direction.', 'Passage étroit. Obligation de céder le passage aux conducteurs venant en sens inverse.', 'ممر ضيق. واجب إعطاء الأولوية للسائقين القادمين من الاتجاه المعاكس.', 'Dit bord geeft aan dat u voorrang moet verlenen aan bestuurders uit de tegenovergestelde richting. U moet stoppen en wachten tot alle bestuurders uit de richting met voorrang zijn gepasseerd.', 'This sign gives priority to drivers coming from the front or opposite direction. You must stop and wait until all drivers from the direction with priority have passed.', 'Ce panneau donne la priorité aux conducteurs venant de l''avant ou du sens inverse. Vous devez vous arrêter et attendre que tous les conducteurs de la direction prioritaire soient passés.', 'تعطي هذه الإشارة الأولوية للسائقين القادمين من الأمام أو الاتجاه المعاكس. يجب عليك التوقف والانتظار حتى يمر جميع السائقين من الاتجاه ذي الأولوية.', 'images/signs/priority_signs/B19 Smalle doorgang. Voorrang verlenen aan de bestuurders die uit de tegenovergestelde richting komen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B21', 'Voorrang op tegenliggers', 'Priority over oncoming traffic', 'Priorité sur les véhicules venant en sens inverse', 'حق أولوية المرور', 'Smalle doorgang. Voorrang ten opzichte van de bestuurders die uit de tegenovergestelde richting komen.', 'Narrow passage. Priority over drivers from the opposite direction.', 'Passage étroit. Priorité par rapport aux conducteurs venant en sens inverse.', 'ممر ضيق. أولوية على السائقين القادمين من الاتجاه المعاكس.', 'Dit bord geeft aan dat u voorrang heeft op het verkeer uit de tegenovergestelde richting. Bestuurders die uit de tegenovergestelde richting komen moeten stoppen en wachten tot de bestuurders in de aangegeven richting zijn gepasseerd.', 'This sign indicates your right of way in the specified direction (in this case forward). Drivers coming from the opposite direction must stop and wait until drivers in the specified direction have passed.', 'Ce panneau indique votre droit de passage dans la direction indiquée (dans ce cas vers l''avant). Les conducteurs venant en sens inverse doivent s''arrêter et attendre que les conducteurs dans la direction indiquée soient passés.', 'تشير هذه العلامة إلى حقك في الطريق في الاتجاه المحدد (في هذه الحالة إلى الأمام). يجب على السائقين القادمين من الاتجاه المعاكس التوقف والانتظار حتى مرور السائقين في الاتجاه المحدد.', 'images/signs/priority_signs/B21 Voorrang op tegenliggers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='B'), 'B22', 'Fietsers mogen rechtsaf bij rood licht', 'Cyclists may turn right at red light', 'Les cyclistes peuvent tourner à droite au feu rouge', 'يجوز لراكبي الدراجات الانعطاف إلى اليمين عند الإشارة الحمراء', 'Fietsers mogen rechtsaf slaan, wanneer het verkeerslicht op rood of oranjegeel staat, op voorwaarde dat zij hierbij voorrang verlenen aan de andere weggebruikers.', 'Cyclists may turn right when traffic light is red or amber, provided they give way to other road users.', 'Les cyclistes peuvent tourner à droite au feu rouge ou orange, à condition de céder le passage aux autres usagers.', 'يجوز لراكبي الدراجات الانعطاف إلى اليمين عندما تكون إشارة المرور حمراء أو كهرمانية، بشرط إفساح المجال لمستخدمي الطريق الآخرين.', 'Dit bord wordt geplaatst bij kruispunten met fietspaden. Fietsers mogen rechtsaf slaan ook bij rood licht, maar moeten voorrang verlenen aan andere weggebruikers (zoals auto''s en voetgangers) op de hoofdweg.', 'This sign is placed at intersections with bicycle paths. Cyclists are allowed to turn right even when the light is red, provided they give priority to other road users (such as cars and pedestrians) on the main road.', 'Ce panneau est placé aux intersections avec des pistes cyclables. Les cyclistes peuvent tourner à droite même lorsque le feu est rouge, à condition de céder la priorité aux autres usagers de la route (comme les voitures et les piétons) sur la route principale.', 'توضع هذه العلامة عند التقاطعات مع مسارات الدراجات. يُسمح لراكبي الدراجات بالانعطاف إلى اليمين حتى عندما يكون الضوء أحمر، بشرط إعطاء الأولوية لمستخدمي الطريق الآخرين (مثل السيارات والمشاة) على الطريق الرئيسي.', 'images/signs/priority_signs/B22 Fietsers en speed pedelecs mogen rechts afslaan en de verkeerslichten voorbijrijden.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C1', 'Verboden richting voor iedere bestuurder', 'No entry for all vehicles', 'Sens interdit pour tout conducteur', 'ممنوع الدخول باتجاه واحد', 'Verboden rijrichting voor alle bestuurders.', 'No entry for any driver.', 'Sens interdit pour tout conducteur.', 'ممنوع الدخول لجميع السائقين.', 'Dit bord geeft aan dat het verboden is om deze weg in te rijden. Het wordt geplaatst aan het einde van eenrichtingsstraten en geeft aan dat de toegang voor alle voertuigen verboden is.', 'This sign indicates that vehicles are completely prohibited from passing in this direction, even if the road is empty. It is placed at the end of one-way roads and indicates that entry is prohibited for all vehicles.', 'Ce panneau indique que les véhicules sont totalement interdits de circuler dans cette direction, même si la route est vide. Il est placé à la fin des routes à sens unique et indique que l''entrée est interdite à tous les véhicules.', 'تشير هذه الإشارة إلى أن المركبات ممنوعة تماماً من المرور في هذا الاتجاه حتى لو كان الطريق خالياً. يتم وضعها في نهاية الطرق ذات الاتجاه الواحد وتشير إلى منع دخول جميع المركبات.', 'images/signs/prohibition_signs/C1 Verboden richting voor iedere bestuurder.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C3', 'Verboden toegang in beide richtingen', 'No entry in both directions', 'Accès interdit dans les deux sens', 'ممنوع الدخول في كلا الاتجاهين', 'Verboden toegang in beide richtingen voor alle bestuurders.', 'No entry in both directions for any driver.', 'Accès interdit dans les deux sens pour tout conducteur.', 'ممنوع الدخول في الاتجاهين لأي سائق.', 'Dit bord geeft aan dat de toegang in beide richtingen verboden is voor alle voertuigen. Het wordt gebruikt bij tijdelijk afgesloten wegen of speciale gebieden waar helemaal geen doorgang is toegestaan.', 'This sign indicates that traffic is prohibited in both directions for all vehicles. It is used on temporarily closed roads or special areas where no passage is allowed at all.', 'Ce panneau indique que la circulation est interdite dans les deux sens pour tous les véhicules. Il est utilisé sur les routes temporairement fermées ou les zones spéciales où aucun passage n''est autorisé.', 'تشير هذه الإشارة إلى أن حركة المرور محظورة في الاتجاهين لجميع المركبات. يتم استخدامه على الطرق المغلقة مؤقتًا أو المناطق الخاصة التي لا يُسمح فيها بالمرور على الإطلاق.', 'images/signs/prohibition_signs/C3 Verboden toegang in beide richtingen voor iedere bestuurder.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C9', 'Verboden toegang voor bestuurders van bromfietsen', 'No moped riders', 'Accès interdit aux conducteurs de cyclomoteurs', 'ممنوع دخول سائقي الدراجات النارية', 'Verboden toegang voor bromfietsen.', 'No entry for mopeds.', 'Accès interdit aux cyclomoteurs.', 'لا يوجد دخول للدراجات البخارية.', 'Dit bord verbiedt de toegang voor bestuurders van bromfietsen. Bromfietsen zijn motorvoertuigen met twee of drie wielen, uitgerust met een motor met een maximale cilinderinhoud van 50 cc. Ze mogen deze weg niet gebruiken. Dit bord wordt vaak geplaatst op wegen waar bromfietsen voor gevaarlijke situaties kunnen zorgen, zoals in voetgangerszones of op bepaalde fietspaden.', 'This sign prohibits access for moped riders. Mopeds are motor vehicles with two or three wheels equipped with an engine with a maximum cylinder capacity of 50 cc. They are not allowed to use this road. This sign is often placed on roads where mopeds could cause dangerous situations, such as in pedestrian zones or on certain bicycle paths.', 'Ce panneau interdit l''accès aux conducteurs de cyclomoteurs. Les cyclomoteurs sont des véhicules à moteur à deux ou trois roues équipés d''un moteur d''une cylindrée maximale de 50 cc. Ils ne peuvent pas emprunter cette route. Ce panneau est souvent placé sur des routes où les cyclomoteurs pourraient créer des situations dangereuses, comme dans les zones piétonnes ou sur certaines pistes cyclables.', 'هذه العلامة تمنع دخول راكبي الدراجات البخارية. الدراجات البخارية هي مركبات ذات عجلتين أو ثلاث عجلات مزودة بمحرك بسعة أسطوانة قصوى تبلغ 50 سم مكعب. ولا يجوز لهم استخدام هذا الطريق. غالبًا ما يتم وضع هذه العلامة على الطرق التي يمكن أن تسبب فيها الدراجات البخارية مواقف خطيرة، كما هو الحال في مناطق المشاة أو على مسارات معينة للدراجات.', 'images/signs/prohibition_signs/C9 Verboden toegang voor bestuurders van bromfietsen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C11', 'Verboden toegang voor bestuurders van rijwielen', 'No entry for riders of bicycles', 'Accès interdit aux conducteurs de bicyclettes', 'ممنوع دخول راكبي الدراجات الهوائية', 'Verboden toegang voor bestuurders van rijwielen.', 'No entry for riders of bicycles.', 'Accès interdit aux conducteurs de bicyclettes.', 'ممنوع دخول راكبي الدراجات الهوائية.', 'Geeft aan dat de toegang verboden is voor bestuurders van rijwielen.', 'Indicates that access is prohibited for riders of bicycles.', 'Indique que l''accès est interdit aux conducteurs de bicyclettes.', 'تشير إلى أن الدخول ممنوع على راكبي الدراجات الهوائية.', 'images/signs/prohibition_signs/C11 Verboden toegang voor bestuurders van rijwielen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C13', 'Verboden toegang voor bestuurders van gespannen', 'No horse-drawn vehicles', 'Accès interdit aux véhicules à traction animale', 'ممنوع دخول العربات التي تجرها خيول أو حيوانات', NULL, NULL, NULL, NULL, 'Dit bord verbiedt de toegang voor door dieren getrokken voertuigen. Dit verbod wordt gebruikt op moderne wegen of in steden om het verkeer vlot te houden en de veiligheid van alle weggebruikers te waarborgen.', 'This sign prohibits access for animal-drawn vehicles. This prohibition is used on modern roads or in cities to reduce traffic slowdowns and ensure the safety of all road users.', 'Ce panneau interdit l''accès aux véhicules à traction animale. Cette interdiction est utilisée sur les routes modernes ou dans les villes pour réduire les ralentissements de la circulation et assurer la sécurité de tous les usagers de la route.', 'هذه العلامة تمنع دخول المركبات التي تجرها الحيوانات. ويستخدم هذا المنع على الطرق الحديثة أو في المدن للحد من التباطؤ المروري وضمان سلامة جميع مستخدمي الطريق.', 'images/signs/prohibition_signs/C13 Verboden toegang voor bestuurders van gespannen..png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C15', 'Verboden toegang voor ruiters', 'No horse riders', 'Accès interdit aux cavaliers', 'ممنوع دخول الخيّالة', 'Verboden toegang voor ruiters.', NULL, NULL, NULL, 'Dit bord verbiedt de toegang voor ruiters te paard. Het wordt vaak geplaatst in stedelijke gebieden of op snelwegen die niet geschikt zijn voor dit type verkeer, ter bescherming van de veiligheid van ruiter en paard.', 'This sign prohibits access for horse riders. It is often placed in urban areas or on highways that are not suitable for this type of traffic, to protect the safety of rider and horse.', 'Ce panneau interdit l''accès aux cavaliers. Il est souvent placé dans les zones urbaines ou sur les autoroutes qui ne conviennent pas à ce type de circulation, pour protéger la sécurité du cavalier et du cheval.', 'هذه العلامة تمنع دخول راكبي الخيل. غالبًا ما يتم وضعها في المناطق الحضرية أو على الطرق السريعة غير المناسبة لهذا النوع من حركة المرور، وذلك حفاظًا على سلامة الفارس والحصان.', 'images/signs/prohibition_signs/C15 Verboden toegang voor ruiters.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C17', 'Verboden toegang voor bestuurders van handkarren', 'No handcarts', 'Accès interdit aux charrettes à bras', 'لا عربات اليد', NULL, NULL, NULL, NULL, 'Dit bord verbiedt de toegang voor personen die handkarren gebruiken of duwen. Dit wordt vaak geplaatst op snelwegen om opstoppingen of ongevallen door trage beweging te voorkomen.', 'This sign prohibits access for persons using or pushing handcarts. It is usually placed on highways to avoid congestion or accidents due to slow movement.', 'Ce panneau interdit l''accès aux personnes utilisant ou poussant des charrettes à bras. Il est généralement placé sur les autoroutes pour éviter les embouteillages ou les accidents dus à la lenteur de déplacement.', 'تمنع هذه العلامة المرورية دخول الأشخاص الذين يستخدمون أو يدفعون عربات اليد. وعادة ما يتم وضعها على الطرق السريعة لتجنب الازدحام أو الحوادث بسبب بطء الحركة.', 'images/signs/prohibition_signs/C17 Verboden toegang voor bestuurders van handkarren.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C19', 'Verboden toegang voor voetgangers', 'No pedestrians', 'Accès interdit aux piétons', 'ممنوع دخول المشاة (الراجلين)', 'Verboden toegang voor voetgangers.', 'No entry for pedestrians.', 'Accès interdit aux piétons.', 'ممنوع الدخول للمشاة.', 'Dit bord verbiedt de toegang voor voetgangers. Het wordt vaak geplaatst op gevaarlijke plaatsen zoals tunnels, snelwegen of gebieden met zwaar verkeer, waar onvoldoende bescherming voor voetgangers beschikbaar is.', 'This sign prohibits access for pedestrians. It is often placed in dangerous locations such as tunnels, highways, or areas with heavy vehicle traffic, where insufficient protection for pedestrians is available.', 'Ce panneau interdit l''accès aux piétons. Il est souvent placé dans des endroits dangereux comme les tunnels, les autoroutes ou les zones à forte circulation de véhicules, où la protection des piétons est insuffisante.', 'هذه العلامة تمنع وصول المشاة. غالبًا ما يتم وضعها في مواقع خطيرة مثل الأنفاق أو الطرق السريعة أو المناطق ذات حركة مرور المركبات الكثيفة، حيث لا تتوفر حماية كافية للمشاة.', 'images/signs/prohibition_signs/C19 Verboden toegang voor voetgangers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C21', 'Verboden toegang voor voertuigen met een massa groter dan aangeduid', 'No vehicles exceeding indicated weight', 'Accès interdit aux véhicules dépassant le poids indiqué', 'ممنوع دخول المركبات التي يتجاوز وزنها', 'Verboden toegang voor voertuigen waarvan de toegelaten massa hoger is dan aangegeven.', 'No entry for vehicles with laden weight exceeding indicated mass.', 'Accès interdit aux véhicules dont la masse en charge dépasse la masse indiquée.', 'ممنوع الدخول للمركبات التي تتجاوز كتلتها المحملة الكتلة المحددة.', 'Dit bord verbiedt de toegang voor voertuigen waarvan de totale massa (inclusief lading) hoger is dan de aangeduide massa. Het wordt meestal gebruikt om bruggen, zwakke wegen of woonwijken te beschermen tegen schade door zware vrachtwagens.', 'This sign prohibits access for vehicles whose total mass (including load) exceeds the indicated mass. It is usually used to protect bridges, weak roads, or residential areas from damage caused by heavy trucks.', 'Ce panneau interdit l''accès aux véhicules dont la masse totale (y compris la charge) dépasse la masse indiquée. Il est généralement utilisé pour protéger les ponts, les routes fragiles ou les zones résidentielles des dommages causés par les camions lourds.', 'تمنع هذه الشاخصة دخول المركبات التي يتجاوز إجمالي كتلتها (بما في ذلك الحمولة) الكتلة المشار إليها. وعادة ما يستخدم لحماية الجسور أو الطرق الضعيفة أو المناطق السكنية من الأضرار التي تسببها الشاحنات الثقيلة.', 'images/signs/prohibition_signs/C21 Verboden toegang voor voertuigen met een massa groter dan aangeduid.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C22', 'Verboden toegang voor bestuurders van autocars', 'No entry for drivers of coaches', 'Accès interdit aux conducteurs d''autocars', 'ممنوع دخول سائقي الحافلات السياحية', 'Verboden toegang voor bestuurders van autocars.', 'Indicates that access is prohibited for drivers of coaches.', 'Indique que l''accès est interdit aux conducteurs d''autocars.', 'تشير إلى أن الدخول ممنوع على سائقي الحافلات السياحية.', 'Geeft aan dat de toegang verboden is voor bestuurders van autocars.', 'Indicates that access is prohibited for drivers of coaches.', 'Indique que l''accès est interdit aux conducteurs d''autocars.', 'تشير إلى أن الدخول ممنوع على سائقي الحافلات السياحية.', 'images/signs/prohibition_signs/C22 Verboden toegang voor bestuurders van autocars.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C23', 'Verboden toegang voor voertuigen bestemd voor het vervoer van zaken', 'No goods vehicles', 'Accès interdit aux véhicules de transport de marchandises', 'ممنوع دخول المركبات المخصصة لنقل البضائع', 'Verboden toegang voor bestuurders van voertuigen gebruikt voor het vervoer van zaken.', 'No entry for goods vehicles.', 'Accès interdit aux véhicules de transport de marchandises.', 'ممنوع الدخول لمركبات نقل البضائع.', 'Dit bord verbiedt de toegang voor vrachtwagens en voertuigen bestemd voor het vervoer van goederen. Dit verbod wordt meestal gebruikt in woonwijken of smalle straten om geluidsoverlast en trillingen te verminderen, of om schade aan de infrastructuur te voorkomen.', 'This sign prohibits access for trucks and vehicles intended for transporting goods. This prohibition is usually used in residential areas or narrow streets to reduce noise and vibrations, or to avoid damage to the infrastructure.', 'Ce panneau interdit l''accès aux camions et véhicules destinés au transport de marchandises. Cette interdiction est généralement utilisée dans les zones résidentielles ou les rues étroites pour réduire le bruit et les vibrations, ou pour éviter d''endommager l''infrastructure.', 'تمنع هذه الشاخصة دخول الشاحنات والمركبات المخصصة لنقل البضائع. ويستخدم هذا الحظر عادة في المناطق السكنية أو الشوارع الضيقة لتقليل الضوضاء والاهتزازات، أو لتجنب الإضرار بالبنية التحتية.', 'images/signs/prohibition_signs/C23 Verboden toegang voor bestuurders van voertuigen bestemd of gebruikt voor het vervoer van zaken.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C24a', 'Verboden toegang voor voertuigen die gevaarlijke goederen vervoeren', 'No vehicles carrying dangerous goods', 'Accès interdit aux véhicules transportant des marchandises dangereuses', 'ممنوع دخول المركبات التي تنقل مواد خطرة', 'Verboden toegang voor bestuurders van voertuigen die de gevaarlijke goederen vervoeren.', 'No entry for vehicles carrying dangerous goods.', 'Accès interdit aux véhicules transportant des marchandises dangereuses.', 'ممنوع الدخول للمركبات التي تنقل بضائع خطرة.', 'Dit bord verbiedt de toegang voor voertuigen die gevaarlijke goederen vervoeren die een gevaar kunnen vormen voor mensen of het milieu, zoals chemische of giftige stoffen. Dit betreft ADR-transporten.', 'This sign prohibits access for vehicles loaded with dangerous goods that may pose a risk to people or the environment, such as chemical or toxic substances.', 'Ce panneau interdit l''accès aux véhicules chargés de marchandises dangereuses pouvant présenter un risque pour les personnes ou l''environnement, comme les substances chimiques ou toxiques.', 'تمنع هذه العلامة دخول المركبات المحملة بمواد خطرة التي قد تشكل خطراً على الناس أو البيئة، مثل المواد الكيميائية أو السامة.', 'images/signs/prohibition_signs/C24a Verboden toegang voor bestuurders van voertuigen die gevaarlijke goederen vervoeren.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C24b', 'Verboden toegang voor voertuigen die ontvlambare of ontplofbare stoffen vervoeren', 'No vehicles carrying flammable or explosive materials', 'Accès interdit aux véhicules transportant des matières inflammables ou explosives', 'ممنوع دخول المركبات التي تحمل مواد قابلة للاشتعال أو الانفجار', 'Verboden toegang voor bestuurders van voertuigen die de gevaarlijke ontvlambare of ontplofbare stoffen vervoeren.', 'No entry for vehicles carrying flammable or explosive substances.', 'Accès interdit aux véhicules transportant des substances inflammables ou explosives.', 'يمنع دخول المركبات التي تحمل مواد قابلة للاشتعال أو الانفجار.', 'Dit bord verbiedt de toegang voor voertuigen die stoffen vervoeren die gemakkelijk kunnen ontploffen of ontvlammen. Het doel is om het risico op grote ongevallen te verminderen, vooral in gesloten of gevoelige gebieden.', 'This sign prohibits access for vehicles transporting materials that can easily explode or ignite. Its purpose is to reduce the risk of major accidents, especially in enclosed or sensitive areas.', 'Ce panneau interdit l''accès aux véhicules transportant des matières pouvant facilement exploser ou s''enflammer. Son but est de réduire le risque d''accidents majeurs, notamment dans les espaces clos ou sensibles.', 'تمنع هذه العلامة دخول المركبات التي تنقل مواد يمكن أن تنفجر أو تشتعل بسهولة. والغرض منه هو تقليل مخاطر الحوادث الكبرى، وخاصة في المناطق المغلقة أو الحساسة.', 'images/signs/prohibition_signs/C24b Verboden toegang voor bestuurders van voertuigen die gevaarlijke ontvlambare of ontplofbare stoffen vervoeren.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C24c', 'Verboden toegang voor voertuigen die verontreinigende stoffen vervoeren', 'No vehicles carrying polluting materials', 'Accès interdit aux véhicules transportant des matières polluantes', 'ممنوع دخول المركبات التي تنقل مواد ملوثة', 'Verboden toegang voor bestuurders van voertuigen die de gevaarlijke verontreinigende stoffen vervoeren.', 'No entry for vehicles carrying polluting substances.', 'Accès interdit aux véhicules transportant des substances polluantes.', 'ممنوع الدخول للمركبات التي تنقل مواد ملوثة.', 'Dit bord verbiedt de toegang voor voertuigen die stoffen vervoeren die het water of het milieu kunnen vervuilen. Dit bord staat meestal in de buurt van rivieren of milieugebieden.', 'This sign prohibits access for vehicles transporting substances that may pollute water or the environment. This sign is usually found near rivers or environmental protection areas.', 'Ce panneau interdit l''accès aux véhicules transportant des substances pouvant polluer l''eau ou l''environnement. Ce panneau se trouve généralement près des rivières ou des zones de protection environnementale.', 'يمنع دخول المركبات التي تنقل مواد قد تلوث المياه أو البيئة، عادةً ما توجد هذه الإشارة قرب الأنهار أو مناطق الحماية البيئية.', 'images/signs/prohibition_signs/C24c Verboden toegang voor bestuurders van voertuigen die gevaarlijke verontreinigende stoffen vervoeren.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C25', 'Verboden voor voertuigen langer dan het aangeduide', 'No vehicles exceeding indicated length', 'Interdit aux véhicules dépassant la longueur indiquée', 'ممنوع مرور المركبات التي يزيد طولها عن الطول المحدد', NULL, NULL, NULL, NULL, 'Dit bord verbiedt de toegang voor lange voertuigen, zoals vrachtwagens of opleggers die langer zijn dan de aangeduide lengte, vanwege smalle straten of scherpe bochten.', 'This sign prohibits access for long vehicles, such as trucks or trailers that exceed the indicated length, due to narrow streets or sharp turns.', 'Ce panneau interdit l''accès aux véhicules longs, comme les camions ou les remorques dépassant la longueur indiquée, en raison de rues étroites ou de virages serrés.', 'تمنع هذه الشاخصة دخول المركبات الطويلة مثل الشاحنات أو المقطورات التي تتجاوز الطول المحدد بسبب الشوارع الضيقة أو المنعطفات الحادة.', 'images/signs/prohibition_signs/C25 Verboden voor voertuigen langer dan het aangeduide.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C27', 'Verboden voor voertuigen breder dan het aangeduide', 'No vehicles exceeding indicated width', 'Interdit aux véhicules dépassant la largeur indiquée', 'ممنوع مرور المركبات التي يزيد عرضها عن العرض المحدد', NULL, NULL, NULL, NULL, 'Dit bord verbiedt de toegang voor voertuigen die breder zijn dan de aangeduide breedte. Dit kan zijn vanwege veiligheidsredenen of smalle wegen.', 'This sign prohibits access for vehicles that are wider than the indicated width. This may be due to safety reasons or narrow roads.', 'Ce panneau interdit l''accès aux véhicules plus larges que la largeur indiquée. Cela peut être dû à des raisons de sécurité ou à des routes étroites.', 'تمنع هذه العلامة المرورية دخول المركبات التي يزيد عرضها عن العرض المشار إليه. وقد يكون ذلك لأسباب تتعلق بالسلامة أو بسبب ضيق الطريق.', 'images/signs/prohibition_signs/C27 Verboden voor voertuigen breder dan het aangeduide.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C31a', 'Verbod om links af te slaan', 'No left turn', 'Interdiction de tourner à gauche', 'لا يوجد انعطاف لليسار', 'Links afslaan is verboden.', 'No turning in the direction indicated by the arrow at the next intersection.', 'Interdiction de tourner dans la direction indiquée par la flèche au prochain carrefour.', 'عدم الانعطاف في الاتجاه المشار إليه بالسهم عند التقاطع التالي.', 'Dit bord verbiedt het afslaan naar links bij dit kruispunt of deze weg. Het wordt vaak geplaatst om ongevallen te voorkomen of vanwege een eenrichtingsweg in de tegenovergestelde richting.', 'This sign prohibits turning left at this intersection or road. It is often placed to prevent accidents or because there is a one-way road in the opposite direction.', 'Ce panneau interdit de tourner à gauche à cette intersection ou sur cette route. Il est souvent placé pour éviter les accidents ou en raison d''une route à sens unique dans la direction opposée.', 'تمنع هذه الإشارة الانعطاف يسارًا عند هذا التقاطع أو الطريق. غالبًا ما يتم وضعه لمنع وقوع الحوادث أو بسبب وجود طريق ذو اتجاه واحد في الاتجاه المعاكس.', 'images/signs/prohibition_signs/C31a Verbod om links af te slaan.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C31b', 'Verbod om rechts af te slaan', 'No right turn', 'Interdiction de tourner à droite', 'لا يوجد انعطاف لليمين', 'Rechts afslaan is verboden.', 'No turning in the direction indicated by the arrow at the next intersection.', 'Interdiction de tourner dans la direction indiquée par la flèche au prochain carrefour.', 'عدم الانعطاف في الاتجاه المشار إليه بالسهم عند التقاطع التالي.', 'Dit bord verbiedt het afslaan naar rechts bij dit kruispunt of deze weg. Het wordt vaak geplaatst om ongevallen te voorkomen of vanwege een eenrichtingsweg in de tegenovergestelde richting.', 'This sign prohibits turning right at this intersection or road. It is often placed to prevent accidents or because there is a one-way road in the opposite direction.', 'Ce panneau interdit de tourner à droite à cette intersection ou sur cette route. Il est souvent placé pour éviter les accidents ou en raison d''une route à sens unique dans la direction opposée.', 'تمنع هذه الإشارة الانعطاف إلى اليمين عند هذا التقاطع أو الطريق. غالبًا ما يتم وضعه لمنع وقوع الحوادث أو بسبب وجود طريق ذو اتجاه واحد في الاتجاه المعاكس.', 'images/signs/prohibition_signs/C31b Verbod rechts af te slaan.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C29', 'Verboden voor voertuigen hoger dan het aangeduide', 'No vehicles exceeding indicated height', 'Interdit aux véhicules dépassant la hauteur indiquée', 'لا توجد مركبات تتجاوز الارتفاع المشار إليه', NULL, NULL, NULL, NULL, 'Dit bord verbiedt de toegang voor voertuigen die hoger zijn dan de aangeduide hoogte. Dit wordt gebruikt wanneer er gevaar is voor botsing met een laag viaduct of tunnel.', 'This sign prohibits access for vehicles that are higher than the indicated height. It is used when there is a risk of collision with a low bridge or tunnel.', 'Ce panneau interdit l''accès aux véhicules plus hauts que la hauteur indiquée. Il est utilisé lorsqu''il y a un risque de collision avec un pont bas ou un tunnel.', 'تمنع هذه الشاخصة دخول المركبات التي يزيد ارتفاعها عن الارتفاع المشار إليه. يتم استخدامه عندما يكون هناك خطر الاصطدام بجسر أو نفق منخفض.', 'images/signs/prohibition_signs/C29 Verboden voor voertuigen hoger dan het aangeduide.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C33', 'Verbod om te keren', 'No U-turn', 'Interdiction de faire demi-tour', 'لا يوجد منعطف على شكل حرف U', 'Het is verboden om te keren.', 'No U-turn from this sign until the next intersection.', 'Interdiction de faire demi-tour depuis ce panneau jusqu''au prochain carrefour.', 'ممنوع الدوران على شكل حرف U من هذه الإشارة حتى التقاطع التالي.', 'Dit bord verbiedt het maken van een U-bocht of het omkeren van richting. Het wordt gebruikt om verwarring in het verkeer te verminderen, vooral bij grote kruispunten of smalle rijstroken.', 'This sign prohibits making a U-turn or reversing direction. It is used to reduce confusion in traffic, especially at large intersections or narrow lanes.', 'Ce panneau interdit de faire demi-tour ou de changer de direction. Il est utilisé pour réduire la confusion dans la circulation, en particulier aux grands carrefours ou dans les voies étroites.', 'تمنع هذه الإشارة الدوران على شكل حرف U أو الرجوع إلى الاتجاه المعاكس. يتم استخدامه لتقليل الارتباك في حركة المرور، خاصة عند التقاطعات الكبيرة أو الممرات الضيقة.', 'images/signs/prohibition_signs/C33 Verbod om te keren.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C37', 'Einde van het verbod opgelegd door het verkeersbord C35', 'End of overtaking prohibition', 'Fin de l''interdiction de dépasser', 'علامة انتهاء منع التجاوز', 'Einde van het verbod om links in te halen.', 'End of no overtaking zone (C35).', 'Fin de l''interdiction de dépasser (C35).', 'نهاية منطقة منع التجاوز (C35).', 'Dit verkeersbord geeft het einde van het inhaalverbod aan dat door bord C35 werd opgelegd. Vanaf deze locatie is het weer toegestaan om andere voertuigen in te halen, mits de verkeerssituatie dit veilig toelaat.', 'This traffic sign indicates the end of the overtaking prohibition imposed by sign C35. From this location, it is again permitted to overtake other vehicles, provided the traffic situation allows this safely.', 'Ce panneau de signalisation indique la fin de l''interdiction de dépasser imposée par le panneau C35. À partir de cet endroit, il est à nouveau permis de dépasser d''autres véhicules, à condition que la situation de circulation le permette en toute sécurité.', 'تشير هذه العلامة إلى أنك من هذه النقطة وصاعداً يسمح لك بتجاوز المركبات المتواجدة على الطريق بعد أن كان ممنوع، ولكن لا ننسى إلا إذا كان الطريق آمنًا.', 'images/signs/prohibition_signs/C37 Einde verbod opgelegd door het verkeersbord C35.png', TRUE, NOW(), NOW()),
((SELECT id FROM categories WHERE code='C'), 'C39', 'Inhaalverbod voor vrachtwagens', 'No overtaking for trucks', 'Interdiction de dépasser pour les camions', 'ممنوع على الشاحنات أن تتجاوز المركبات الأخرى', 'Zware voertuigen mogen niet inhalen.', 'No overtaking by vehicles over 3,500 kg from this sign until the next intersection.', 'Interdiction de dépasser pour les véhicules de plus de 3 500 kg depuis ce panneau jusqu''au prochain carrefour.', 'يمنع تجاوز المركبات التي يزيد وزنها عن 3500 كجم من هذه الإشارة حتى التقاطع التالي.', 'Dit bord verbiedt vrachtwagens om andere voertuigen in te halen. Het wordt meestal geplaatst op smalle wegen of wegen met beperkt zicht, en soms op snelwegen om de veiligheid van iedereen te garanderen.', 'This sign prohibits trucks from overtaking other vehicles. It is usually placed on narrow roads or roads with limited visibility, and sometimes on highways to ensure everyone''s safety.', 'Ce panneau interdit aux camions de dépasser d''autres véhicules. Il est généralement placé sur des routes étroites ou à visibilité limitée, et parfois sur des autoroutes pour assurer la sécurité de tous.', 'تمنع هذه الإشارة الشاحنات من تجاوز المركبات الأخرى. يتم وضعها عادة على الطرق الضيقة أو الطرق ذات الرؤية المحدودة، وأحياناً على الطرق السريعة لضمان سلامة الجميع.', 'images/signs/prohibition_signs/C39 Verbod voertuigen met toegelaten massa groter dan 3500 kg in te halen.png', TRUE, NOW(), NOW()),
((SELECT id FROM categories WHERE code='C'), 'C43', 'Verbod te rijden met een grotere snelheid dan 50 km', 'Speed limit 50 km/h', 'Limitation de vitesse 50 km/h', 'ممنوع القيادة بسرعة تتجاوز 50 كم/س', 'Maximumsnelheid van 50 km/u.', 'Maximum speed of 50 km/h.', 'Vitesse maximale de 50 km/h.', 'السرعة القصوى 50 كم/س.', 'Dit bord geeft de maximumsnelheid van 50 km/u aan. Het is verboden om sneller te rijden dan het aangegeven aantal km/u. Dit bord wordt vaak geplaatst waar een lage snelheid noodzakelijk is voor de veiligheid.', 'This sign indicates a maximum speed of 50 km/h. It is forbidden to drive faster than the indicated speed in km/h. This sign is often placed where a lower speed is necessary for safety.', 'Ce panneau indique une vitesse maximale de 50 km/h. Il est interdit de rouler plus vite que la vitesse indiquée en km/h. Ce panneau est souvent placé là où une vitesse réduite est nécessaire pour la sécurité.', 'تشير هذه العلامة إلى السرعة القصوى 50 كم/س. يمنع القيادة بسرعة أكبر من السرعة المحددة، وتوضع غالبًا حيث تكون السرعة المنخفضة ضرورية للسلامة.', 'images/signs/prohibition_signs/C43 Verbod te rijden met een grotere snelheid dan 50 km.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C47', 'Tolpost - Verbod voorbij te rijden zonder te stoppen', 'Toll station - No passing without stopping', 'Poste de péage - Interdit de passer sans s''arrêter', 'محطة تحصيل الرسوم - ممنوع المرور دون توقف', NULL, NULL, NULL, NULL, 'Dit bord geeft aan dat je een tolpost nadert. Alle voertuigen moeten stoppen en betalen voordat ze verder mogen rijden.', 'This sign indicates that you are approaching a toll station. All vehicles must stop and pay before they may continue.', 'Ce panneau indique que vous approchez d''un poste de péage. Tous les véhicules doivent s''arrêter et payer avant de pouvoir continuer.', 'تشير هذه العلامة إلى أنك تقترب من محطة تحصيل الرسوم. يجب على جميع المركبات التوقف والدفع قبل أن تتمكن من الاستمرار.', 'images/signs/prohibition_signs/C47 Tolpost. Verbod voorbij te rijden zonder te stoppen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C45', 'Einde van de snelheidsbeperking opgelegd door het verkeersbord C43', 'End of speed limit 50 km/h', 'Fin de la limitation de vitesse à 50 km/h', 'علامة انتهاء السرعة 50 كم/س', 'Einde van de maximumsnelheid opgelegd door C43.', NULL, NULL, NULL, 'Dit verkeersbord geeft aan dat de snelheidsbeperking van 50 km/u die eerder door verkeersbord C43 was opgelegd, hier eindigt. Vanaf dit punt geldt de algemene snelheidslimiet voor dit type weg, tenzij een nieuw snelheidsbord anders aangeeft.', 'This traffic sign indicates that the 50 km/h speed limit that was previously imposed by traffic sign C43 ends here. From this point, the general speed limit for this type of road applies, unless a new speed sign indicates otherwise.', 'Ce panneau de signalisation indique que la limitation de vitesse de 50 km/h qui avait été imposée par le panneau C43 prend fin ici. À partir de ce point, la limite de vitesse générale pour ce type de route s''applique, sauf indication contraire d''un nouveau panneau de vitesse.', 'تشير هذه العلامة المرورية إلى أن حد السرعة المسموح به 50 كم/ساعة والذي تم فرضه مسبقًا بواسطة العلامة المرورية C43 ينتهي هنا. ومن هذه النقطة، يتم تطبيق حد السرعة العام لهذا النوع من الطرق، ما لم تشير إشارة السرعة الجديدة إلى خلاف ذلك.', 'images/signs/prohibition_signs/C45 Einde van de snelheidsbeperking opgelegd door het verkeersbord C43.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='C'), 'C46', 'Einde van alle plaatselijke verbodsbepalingen opgelegd aan de voertuigen in beweging', 'End of all local prohibitions', 'Fin de toutes les interdictions locales', 'نهاية جميع القيود المحلية (السرعة، التجاوز، إلخ)', NULL, NULL, NULL, NULL, 'Dit verkeersbord geeft aan dat alle plaatselijke verbodsbepalingen die golden voor voertuigen in beweging zijn beëindigd. Dit omvat snelheidsbeperkingen, inhaalverboden en andere tijdelijke beperkingen. Vanaf hier gelden weer de algemene verkeersregels.', 'This traffic sign indicates that all local prohibitions that applied to vehicles in motion have ended. This includes speed limits, overtaking bans and other temporary restrictions. From here, the general traffic rules apply again.', 'Ce panneau de signalisation indique que toutes les interdictions locales qui s''appliquaient aux véhicules en mouvement ont pris fin. Cela comprend les limites de vitesse, les interdictions de dépasser et autres restrictions temporaires. À partir d''ici, les règles générales de circulation s''appliquent à nouveau.', 'تشير إشارة المرور هذه إلى أن جميع المحظورات المحلية المطبقة على المركبات المتحركة قد انتهت. ويشمل ذلك حدود السرعة وحظر التجاوز والقيود المؤقتة الأخرى. ومن هنا يتم تطبيق قواعد المرور العامة مرة أخرى.', 'images/signs/prohibition_signs/C46 Einde van alle plaatselijke verbodsbepalingen opgelegd aan de voertuigen in beweging.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D1a', 'Verplichting rechtdoor', 'Mandatory straight ahead', 'Obligation d''aller tout droit', 'طريق إجباري إلى الأمام', 'Verplichting de door de pijl aangeduide richting te volgen.', 'Obligation to follow the direction indicated by the arrow.', 'Obligation de suivre la direction indiquée par la flèche.', 'واجب اتباع الاتجاه المحدد بالسهم.', 'Dit verkeersbord verplicht bestuurders om rechtdoor te rijden. Het is niet toegestaan om af te slaan of van richting te veranderen naar links of rechts.', 'This traffic sign requires drivers to continue driving straight ahead only. They are not allowed to turn or change direction to the right or left.', 'Ce panneau de signalisation oblige les conducteurs à continuer tout droit. Il n''est pas permis de tourner ou de changer de direction vers la droite ou la gauche.', 'تتطلب إشارة المرور هذه من السائقين مواصلة القيادة للأمام مباشرة فقط. ولا يجوز لهم الانعطاف أو تغيير الاتجاه إلى اليمين أو اليسار.', 'images/signs/mandatory_signs/D1a Verplichting rechtdoor.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D1c', 'Verplichting links aanhouden', 'Obligation to keep left', 'Obligation de serrer à gauche', 'الالتزام باتجاه اليسار (ميلان الطريق)', NULL, NULL, NULL, NULL, 'Dit verkeersbord wordt geplaatst bij kruispunten met een lichte verplichte bocht naar links (bijvoorbeeld bij een middeneiland). Het geeft aan dat je in deze richting moet rijden om niet tegen het verkeer in te rijden.', 'This traffic sign is placed at intersections with a slight mandatory curve to the left (for example at a central island). It indicates that you must drive in this direction to avoid driving against traffic.', 'Ce panneau est placé aux carrefours avec un virage obligatoire léger vers la gauche (par exemple à un îlot central). Il indique que vous devez conduire dans cette direction pour éviter de rouler à contre-sens.', 'يتم وضع علامة المرور هذه عند التقاطعات مع منحنى إلزامي طفيف إلى اليسار (على سبيل المثال عند جزيرة مركزية). يشير إلى أنه يجب عليك القيادة في هذا الاتجاه لتجنب القيادة عكس حركة المرور.', 'assets/signs/gebodsborden/D1c Verplichting links aanhouden.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D1d', 'Verplichting rechts aanhouden', 'Obligation to keep right', 'Obligation de serrer à droite', 'الالتزام باتجاه اليمين (ميلان الطريق)', NULL, NULL, NULL, NULL, 'Dit verkeersbord wordt geplaatst bij kruispunten met een lichte verplichte bocht naar rechts (bijvoorbeeld bij een middeneiland). Het geeft aan dat je in deze richting moet rijden om niet tegen het verkeer in te rijden.', 'This traffic sign is placed at intersections with a slight mandatory curve to the right (for example at a central island). It indicates that you must drive in this direction to avoid driving against traffic.', 'Ce panneau est placé aux carrefours avec un virage obligatoire léger vers la droite (par exemple à un îlot central). Il indique que vous devez conduire dans cette direction pour éviter de rouler à contre-sens.', 'يتم وضع علامة المرور هذه عند التقاطعات مع منحنى إلزامي طفيف إلى اليمين (على سبيل المثال، عند جزيرة مركزية). يشير إلى أنه يجب عليك القيادة في هذا الاتجاه لتجنب القيادة عكس حركة المرور.', 'assets/signs/gebodsborden/D1d Verplichting rechts aanhouden.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D1b-links', 'Verplichting links afslaan', 'Mandatory left turn', 'Obligation de tourner à gauche', 'إلزامية القيادة باتجاه اليسار', 'Verplichting de door de pijl aangeduide richting te volgen.', 'Obligation to follow the direction indicated by the arrow.', 'Obligation de suivre la direction indiquée par la flèche.', 'واجب اتباع الاتجاه المحدد بالسهم.', 'Dit verkeersbord verplicht bestuurders om naar links af te slaan. Het is alleen toegestaan om in deze richting te rijden en het is niet toegestaan om naar rechts of rechtdoor te gaan.', 'This traffic sign requires drivers to turn left. They must continue in this direction only and are not allowed to ignore this sign or change direction to the right or straight ahead.', 'Ce panneau de signalisation oblige les conducteurs à tourner à gauche. Ils doivent continuer dans cette direction uniquement et ne sont pas autorisés à ignorer ce panneau ou à changer de direction vers la droite ou tout droit.', 'تتطلب إشارة المرور هذه من السائقين الانعطاف إلى اليسار. وعليهم الاستمرار في هذا الاتجاه فقط ولا يجوز لهم تجاهل هذه الإشارة أو تغيير الاتجاه إلى اليمين أو إلى الأمام مباشرة.', 'images/signs/mandatory_signs/D1b Verplichting links afslaan.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D1c', 'Verplichting rechts afslaan', 'Mandatory right turn', 'Obligation de tourner à droite', 'إلزامية القيادة باتجاه اليمين', 'Verplichting de door de pijl aangeduide richting te volgen.', 'Obligation to follow the direction indicated by the arrow.', 'Obligation de suivre la direction indiquée par la flèche.', 'واجب اتباع الاتجاه المحدد بالسهم.', 'Dit verkeersbord verplicht bestuurders om naar rechts af te slaan. Het is alleen toegestaan om in deze richting te rijden en het is niet toegestaan om naar links of rechtdoor te gaan.', 'This traffic sign requires drivers to turn right. They must continue in this direction only and are not allowed to ignore this sign or change direction to the left or straight ahead.', 'Ce panneau de signalisation oblige les conducteurs à tourner à droite. Ils doivent continuer dans cette direction uniquement et ne sont pas autorisés à ignorer ce panneau ou à changer de direction vers la gauche ou tout droit.', 'تتطلب إشارة المرور هذه من السائقين الانعطاف إلى اليمين. وعليهم الاستمرار في هذا الاتجاه فقط ولا يجوز لهم تجاهل هذه الإشارة أو تغيير الاتجاه إلى اليسار أو إلى الأمام مباشرة.', 'images/signs/mandatory_signs/D1c Verplichting links aanhouden.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D1e', 'Verplicht de aangeduide richting te volgen (linksaf)', 'Mandatory turn left', 'Obligation de tourner à gauche', 'الانعطاف الإلزامي إلى اليسار', 'Verplichting de door de pijl aangeduide richting te volgen.', 'Obligation to follow the direction indicated by the arrow.', 'Obligation de suivre la direction indiquée par la flèche.', 'واجب اتباع الاتجاه المحدد بالسهم.', 'Dit verkeersbord wordt geplaatst op smalle kruispunten of in speciale doorgangen zoals parkeerplaatsen of woongebieden. Het verplicht de bestuurder om naar links af te slaan en verbiedt rechtdoor of naar rechts te rijden.', 'This traffic sign is placed at narrow intersections or in special passages such as parking areas or residential areas. It requires the driver to turn left and prohibits driving straight ahead or to the right.', 'Ce panneau est placé aux carrefours étroits ou dans des passages spéciaux comme les aires de stationnement ou les zones résidentielles. Il oblige le conducteur à tourner à gauche et interdit d''aller tout droit ou à droite.', 'توضع هذه العلامة المرورية عند التقاطعات الضيقة أو في الممرات الخاصة مثل مواقف السيارات أو المناطق السكنية. يتطلب من السائق الانعطاف إلى اليسار ويمنع القيادة إلى الأمام أو إلى اليمين.', 'images/signs/mandatory_signs/D1e Verplicht links afslaan.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D10', 'Deel van de weg voorbehouden voor voetgangers en fietsers', 'Shared path for pedestrians and cyclists', 'Chemin partagé pour piétons et cyclistes', 'مسار مشترك للمشاة وراكبي الدراجات', 'Deel van de openbare weg voorbehouden voor het verkeer van voetgangers en fietsers.', 'Path reserved for pedestrians and cyclists.', 'Chemin réservé aux piétons et cyclistes.', 'مسار مخصص للمشاة وراكبي الدراجات.', 'Dit verkeersbord verplicht voetgangers en fietsers of scooters om samen dit pad of deze weg te gebruiken. Het wordt meestal gebruikt in parken of rustige straten.', 'This traffic sign requires pedestrians and cyclists or scooters to use this path or road together. It is usually used in parks or quiet streets.', 'Ce panneau oblige les piétons et les cyclistes ou trottinettes à utiliser ce chemin ou cette route ensemble. Il est généralement utilisé dans les parcs ou les rues calmes.', 'تتطلب إشارة المرور هذه من المشاة وراكبي الدراجات أو الدراجات البخارية استخدام هذا المسار أو الطريق معًا. وعادة ما يستخدم في الحدائق أو الشوارع الهادئة.', 'images/signs/mandatory_signs/D10 Deel van de weg voorbehouden voor voetgangers en fietsers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='D'), 'D13', 'Verplichte weg voor ruiters', 'Mandatory path for horse riders', 'Chemin obligatoire pour cavaliers', 'طريق إجباري مخصص لراكبي الخيل', 'Bestuurders mogen links of rechts langs het obstakel rijden.', NULL, NULL, NULL, 'Dit bord geeft een verplicht ruiterpad aan. Ruiters moeten dit pad gebruiken. Voetgangers en voertuigen mogen dit pad niet gebruiken. Dit bord wordt vaak geplaatst in grote parken of landelijke gebieden met paardenfokkerijen.', 'This sign indicates a mandatory path for horse riders. Horse riders must use this path. Pedestrians and vehicles are not allowed on this path. This sign is often placed in large parks or rural areas with horse farms.', 'Ce panneau indique un chemin obligatoire pour les cavaliers. Les cavaliers doivent emprunter ce chemin. Les piétons et les véhicules ne peuvent pas utiliser ce chemin. Ce panneau est souvent placé dans les grands parcs ou les zones rurales avec des élevages de chevaux.', 'تشير هذه العلامة إلى مسار إلزامي لراكبي الخيل. يجب على راكبي الخيل استخدام هذا المسار. لا يسمح للمشاة والمركبات بالسير على هذا الطريق. غالبًا ما يتم وضع هذه العلامة في الحدائق الكبيرة أو المناطق الريفية التي بها مزارع الخيول.', 'images/signs/mandatory_signs/D13 Verplichte weg voor ruiters.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC1', 'Einde zone verboden toegang (uitzondering laden/lossen)', 'End of no entry zone (except loading/unloading)', 'Fin de zone d''accès interdit (exception chargement/déchargement)', 'نهاية منطقة عدم الدخول (باستثناء التحميل/التفريغ)', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar toegang verboden was, met uitzondering van voertuigen die de zone betraden voor laden of lossen. Vanaf dit punt gelden deze specifieke beperkingen niet meer, en zijn de algemene verkeersregels van toepassing, tenzij een ander verkeersbord andere voorwaarden voor toegang of uitzondering aangeeft.', 'This traffic sign indicates the end of the zone where entry was prohibited, except for vehicles entering for loading or unloading purposes only. From this point onwards, these specific restrictions end, and general traffic rules apply, unless another traffic sign specifies different conditions for entry or exception.', 'Ce panneau de signalisation indique la fin de la zone où l''accès était interdit, à l''exception des véhicules entrant uniquement pour charger ou décharger. À partir de ce point, ces restrictions spécifiques prennent fin, et les règles générales de circulation s''appliquent, sauf si un autre panneau de signalisation indique des conditions différentes d''entrée ou d''exception.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة المحظور دخولها، باستثناء المركبات الداخلة لأغراض التحميل أو التفريغ فقط. ومن الآن فصاعدا، تنتهي هذه القيود المحددة، وتطبق قواعد المرور العامة، ما لم تحدد علامة مرورية أخرى شروطا مختلفة للدخول أو الاستثناء.', 'images/signs/zone_signs/ZC1 Zone verboden toegang Herhaling.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC5', 'Zone verboden toegang motorvoertuigen met meer dan 2 wielen', 'Zone no entry for motor vehicles with more than 2 wheels', 'Zone d''accès interdit aux véhicules à moteur à plus de 2 roues', 'منطقة منع دخول المركبات الآلية ذات أكثر من عجلتين', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin aan van een zone waar motorvoertuigen met meer dan twee wielen, zoals auto''s en vrachtwagens, niet mogen rijden. Alleen voertuigen die wettelijk zijn uitgezonderd, zoals fietsen of voertuigen met een uitzondering aangegeven door een onderbord, zijn toegestaan. Dit verbod geldt voor alle wegen in de zone totdat een bord het einde van de zone aangeeft of de toegangsvoorwaarden wijzigt.', 'This traffic sign indicates the beginning of a zone where motor vehicles with more than two wheels, such as cars and trucks, are not allowed to enter. Only vehicles that are legally exempt, such as bicycles or vehicles with an exception indicated by a supplementary sign, are permitted. This prohibition applies to all roads in the zone until a sign announces the end of the zone or changes the entry conditions.', 'Ce panneau de signalisation indique le début d''une zone où les véhicules à moteur de plus de deux roues, tels que les voitures et les camions, ne sont pas autorisés à entrer. Seuls les véhicules légalement exemptés, tels que les vélos ou les véhicules bénéficiant d''une exception indiquée par un panneau supplémentaire, sont autorisés. Cette interdiction s''applique à toutes les routes de la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie les conditions d''entrée.', 'تشير هذه العلامة المرورية إلى بداية المنطقة التي لا يسمح بدخول المركبات ذات أكثر من عجلتين، مثل السيارات والشاحنات. يُسمح فقط بالمركبات المعفاة قانونًا، مثل الدراجات الهوائية أو المركبات مع استثناء موضح بعلامة تكميلية. ويسري هذا المنع على جميع الطرق في المنطقة حتى ظهور علامة تعلن انتهاء المنطقة أو تغيير شروط الدخول.', 'images/signs/zone_signs/ZC5 Einde zone verboden toegang voor motorvoertuigen met meer dan 2 wielen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC5-v1', 'Einde zone verboden toegang motorvoertuigen met meer dan 2 wielen', 'End of zone no entry for motor vehicles with more than 2 wheels', 'Fin de zone d''accès interdit aux véhicules à moteur à plus de 2 roues', 'نهاية منطقة منع دخول المركبات الآلية ذات أكثر من عجلتين', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar motorvoertuigen met meer dan twee wielen, zoals auto''s en vrachtwagens, niet mochten rijden. Vanaf dit punt geldt dit zoneverbod niet meer, en zijn de algemene verkeersregels van toepassing volgens de verkeersborden en andere wegmarkeringen ter plaatse.', 'This traffic sign indicates the end of the zone where motor vehicles with more than two wheels, such as cars and trucks, were not allowed to enter. From this point onwards, this zone prohibition ends, and general traffic rules apply according to the road signs and other traffic markings in place.', 'Ce panneau de signalisation indique la fin de la zone où les véhicules à moteur de plus de deux roues, tels que les voitures et les camions, n''étaient pas autorisés à entrer. À partir de ce point, cette interdiction de zone prend fin, et les règles générales de circulation s''appliquent selon les panneaux de signalisation et autres marquages routiers en place.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي لا يسمح بدخول المركبات ذات أكثر من عجلتين، مثل السيارات والشاحنات. من هذه النقطة فصاعدًا، ينتهي حظر المنطقة هذا، ويتم تطبيق قواعد المرور العامة وفقًا لعلامات الطريق وعلامات المرور الأخرى الموجودة.', 'assets/signs/zoneborden/ZC5 Zone verboden toegang voor motorvoertuigen met meer dan 2 wielen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC14', 'Zone fietsstraat', 'Bicycle street zone', 'Zone rue cyclable', 'منطقة شارع الدراجات الهوائية', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin aan van een zone met een fietsstraat, waar fietsen de hoofdgebruiker van de weg zijn. Binnen deze zone moeten andere bestuurders fietsers respecteren, niet inhalen, en met een lage snelheid rijden die is aangepast aan het fietsverkeer. Deze regels gelden voor de hele zone totdat een bord het einde van de fietsstraatzone aangeeft of het verkeersregime wijzigt.', 'This traffic sign indicates the beginning of a bicycle street zone, where bicycles are the main road user. Within this zone, other drivers must respect cyclists, not overtake them, and drive at a low speed adapted to bicycle traffic. These rules apply to the entire zone until a sign announces the end of the bicycle street zone or changes the traffic regime.', 'Ce panneau de signalisation indique le début d''une zone de rue cyclable, où les vélos sont les principaux usagers de la route. Dans cette zone, les autres conducteurs doivent respecter les cyclistes, ne pas les dépasser, et rouler à faible vitesse adaptée à la circulation cycliste. Ces règles s''appliquent à toute la zone jusqu''à ce qu''un panneau annonce la fin de la zone de rue cyclable ou modifie le régime de circulation.', 'تشير إشارة المرور هذه إلى بداية منطقة شارع مخصص للدراجات، حيث تكون الدراجات هي المستخدم الرئيسي للطريق. داخل هذه المنطقة، يجب على السائقين الآخرين احترام راكبي الدراجات وعدم تجاوزهم والقيادة بسرعة منخفضة تتكيف مع حركة مرور الدراجات. تنطبق هذه القواعد على المنطقة بأكملها حتى تعلن علامة نهاية منطقة شارع الدراجات أو تغير نظام المرور.', 'images/signs/zone_signs/ZC14 ZONE Fietsstraat.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC21', 'Zone verboden toegang voertuigen +3,5t', 'Zone no entry for vehicles over 3.5t', 'Zone d''accès interdit aux véhicules de plus de 3,5t', 'منطقة منع دخول المركبات التي يتجاوز وزنها 3.5 طن', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar voertuigen met een toegestane maximummassa van meer dan 3,5 ton niet mogen rijden. Binnen deze zone is het niet toegestaan voor vrachtwagens of zware voertuigen die dit gewicht overschrijden om te rijden, en dit verbod geldt voor alle wegen in de zone totdat een bord het einde van de zone aangeeft of de toegangsvoorwaarden wijzigt.', 'This traffic sign indicates the beginning of a zone where vehicles with an authorized maximum mass exceeding 3.5 tons are not allowed to enter. Within this zone, trucks or heavy vehicles exceeding this weight are not permitted to drive, and this prohibition applies to all roads in the zone until a sign announces the end of the zone or changes the entry conditions.', 'Ce panneau de signalisation indique le début d''une zone où les véhicules dont la masse maximale autorisée dépasse 3,5 tonnes ne sont pas autorisés à entrer. Dans cette zone, les camions ou véhicules lourds dépassant ce poids ne sont pas autorisés à circuler, et cette interdiction s''applique à toutes les routes de la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie les conditions d''entrée.', 'تشير إشارة المرور هذه إلى بداية منطقة لا يُسمح فيها بدخول المركبات التي يزيد وزنها الأقصى المسموح به عن 3.5 طن. ولا يجوز داخل هذه المنطقة قيادة الشاحنات أو المركبات الثقيلة التي يزيد وزنها عن هذا الوزن، وينطبق هذا المنع على جميع الطرق في المنطقة حتى ظهور إشارة تعلن انتهاء المنطقة أو تغيير شروط الدخول.', 'images/signs/zone_signs/ZC21 - Zone verboden toegang voor bestuurders van voertuigen waarvan de massa hoger is dan de aangeduide massa.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC21T', 'Zone verboden toegang voertuigen +3,5t (uitzondering laden/lossen)', 'Zone no entry for vehicles over 3.5t (except loading/unloading)', 'Zone d''accès interdit aux véhicules de plus de 3,5t (exception chargement/déchargement)', 'منطقة ممنوع دخول المركبات التي يزيد وزنها عن 3.5 طن (باستثناء التحميل/التفريغ)', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar voertuigen met een toegestane maximummassa van meer dan 3,5 ton niet mogen rijden. Uitzondering geldt voor voertuigen die de zone betreden voor laden of lossen, mits ze direct na afloop weer vertrekken. Dit verbod geldt voor alle wegen in de zone totdat een bord het einde van de zone aangeeft of de toegangsvoorwaarden wijzigt.', 'This traffic sign indicates the beginning of a zone where vehicles with an authorized maximum mass exceeding 3.5 tons are not allowed to enter. An exception is made for vehicles entering the zone for loading or unloading purposes only, provided they leave immediately after completion. This prohibition applies to all roads in the zone until a sign announces the end of the zone or changes the entry conditions.', 'Ce panneau de signalisation indique le début d''une zone où les véhicules dont la masse maximale autorisée dépasse 3,5 tonnes ne sont pas autorisés à entrer. Une exception est faite pour les véhicules qui entrent dans la zone uniquement pour charger ou décharger, à condition qu''ils partent immédiatement après. Cette interdiction s''applique à toutes les routes de la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie les conditions d''entrée.', 'تشير إشارة المرور هذه إلى بداية منطقة لا يُسمح فيها بدخول المركبات التي يزيد وزنها الأقصى المسموح به عن 3.5 طن. ويستثنى من ذلك المركبات التي تدخل المنطقة لأغراض التحميل أو التفريغ فقط، على أن تغادرها فور الانتهاء منها. ويسري هذا المنع على جميع الطرق في المنطقة حتى ظهور علامة تعلن انتهاء المنطقة أو تغيير شروط الدخول.', 'images/signs/zone_signs/ZC21T Einde zone verboden toegang voor bestuurders van voertuigen waarvan de massa hoger is dan de aangeduide massa.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC21T-v2', 'Einde zone verboden toegang voertuigen +3,5t (uitzondering laden/lossen)', 'End of zone no entry for vehicles over 3.5t (except loading/unloading)', 'Fin de zone d''accès interdit aux véhicules de plus de 3,5t (exception chargement/déchargement)', 'نهاية المنطقة ممنوع دخول المركبات التي يزيد وزنها عن 3.5 طن (باستثناء التحميل/التفريغ)', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar voertuigen met een toegestane maximummassa van meer dan 3,5 ton niet mochten rijden, met uitzondering van voertuigen die de zone betraden voor laden of lossen. Vanaf dit punt gelden deze specifieke beperkingen niet meer, en zijn de algemene verkeersregels van toepassing tenzij een ander verkeersbord andere voorwaarden aangeeft.', 'This traffic sign indicates the end of the zone where vehicles with an authorized maximum mass exceeding 3.5 tons were not allowed to enter, except for vehicles entering for loading or unloading purposes. From this point onwards, these specific restrictions end, and general traffic rules apply unless another traffic sign specifies different conditions.', 'Ce panneau de signalisation indique la fin de la zone où les véhicules dont la masse maximale autorisée dépasse 3,5 tonnes n''étaient pas autorisés à entrer, à l''exception des véhicules entrant pour charger ou décharger. À partir de ce point, ces restrictions spécifiques prennent fin, et les règles générales de circulation s''appliquent sauf si un autre panneau de signalisation indique des conditions différentes.', 'تشير هذه الشاخصة المرورية إلى نهاية المنطقة التي لا يسمح بدخول المركبات التي يزيد الحد الأقصى المسموح بها لكتلتها عن 3.5 طن، باستثناء المركبات التي تدخل لأغراض التحميل أو التفريغ. ومن الآن فصاعدا، تنتهي هذه القيود المحددة، وتطبق قواعد المرور العامة ما لم تحدد إشارة مرور أخرى شروطا مختلفة.', 'assets/signs/zoneborden/ZC21T Zone verboden toegang voor bestuurders van voertuigen waarvan de massa hoger is dan de aangeduide massa.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC35', 'Zone verboden inhalen', 'No overtaking zone', 'Zone d''interdiction de dépasser', 'منطقة ممنوع التجاوز', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar inhalen tussen voertuigen verboden is. Binnen deze zone is het niet toegestaan om andere voertuigen in te halen, ongeacht hun snelheid, en je moet achter het voertuig voor je blijven rijden. Dit verbod geldt voor alle wegen in de zone totdat een bord het einde van de zone aangeeft of de inhaalregel wijzigt.', 'This traffic sign indicates the beginning of a zone where overtaking between vehicles is prohibited. Within this zone, it is not allowed to overtake other vehicles regardless of their speed, and you must stay behind the vehicle in front of you. This prohibition applies to all roads in the zone until a sign announces the end of the zone or changes the overtaking rule.', 'Ce panneau de signalisation indique le début d''une zone où le dépassement entre véhicules est interdit. Dans cette zone, il n''est pas permis de dépasser d''autres véhicules quelle que soit leur vitesse, et vous devez rester derrière le véhicule devant vous. Cette interdiction s''applique à toutes les routes de la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie la règle de dépassement.', 'تشير هذه العلامة المرورية إلى بداية المنطقة التي يُمنع فيها التجاوز بين المركبات. لا يجوز داخل هذه المنطقة تجاوز المركبات الأخرى مهما كانت سرعتها، ويجب عليك البقاء خلف المركبة التي أمامك. وينطبق هذا المنع على جميع الطرق في المنطقة حتى ظهور إشارة تعلن نهاية المنطقة أو تغيير قاعدة التجاوز.', 'images/signs/zone_signs/ZC35 Einde zone verboden inhalen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC35-v1', 'Einde zone verboden inhalen', 'End of no overtaking zone', 'Fin de zone d''interdiction de dépasser', 'نهاية منطقة ممنوع التجاوز', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar inhalen tussen voertuigen verboden was. Vanaf dit punt geldt dit verbod niet meer, en is inhalen weer toegestaan volgens de algemene verkeersregels en afhankelijk van de staat van de weg en andere verkeersborden.', 'This traffic sign indicates the end of the zone where overtaking between vehicles was prohibited. From this point onwards, this prohibition ends, and overtaking is allowed again according to the general traffic rules and depending on the road conditions and other traffic signs.', 'Ce panneau de signalisation indique la fin de la zone où le dépassement entre véhicules était interdit. À partir de ce point, cette interdiction prend fin, et le dépassement est à nouveau autorisé selon les règles générales de circulation et en fonction de l''état de la route et des autres panneaux de signalisation.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي يمنع فيها التجاوز بين المركبات. ومن الآن فصاعداً ينتهي هذا المنع، ويُسمح بالتجاوز مرة أخرى وفقاً لقواعد المرور العامة وحسب حالة الطريق والعلامات المرورية الأخرى.', 'assets/signs/zoneborden/ZC35 Zone verboden inhalen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC35T', 'Zone verboden inhalen', 'No overtaking zone', 'Zone d''interdiction de dépasser', 'منطقة ممنوع التجاوز', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar inhalen tussen voertuigen verboden is. Binnen deze zone is het niet toegestaan om andere voertuigen in te halen, of ze nu langzaam of met een lagere snelheid rijden, en men moet achter het voorliggende voertuig blijven rijden. Dit verbod geldt voor alle wegen in de zone totdat een bord het einde van de zone aangeeft of de inhaalregel wijzigt.', 'This traffic sign indicates the beginning of a zone where overtaking between vehicles is prohibited. Within this zone, it is not allowed to overtake other vehicles, whether they are driving slowly or at a lower speed, and one must stay behind the vehicle in front. This prohibition continues on all roads in the zone until a sign announces the end of the zone or changes the overtaking rule.', 'Ce panneau de signalisation indique le début d''une zone où le dépassement entre véhicules est interdit. Dans cette zone, il n''est pas permis de dépasser d''autres véhicules, qu''ils roulent lentement ou à une vitesse inférieure, et on doit rester derrière le véhicule devant. Cette interdiction s''applique à toutes les routes de la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie la règle de dépassement.', 'تشير هذه العلامة المرورية إلى بداية المنطقة التي يُمنع فيها التجاوز بين المركبات. لا يجوز داخل هذه المنطقة تجاوز المركبات الأخرى سواء كانت تسير ببطء أو بسرعة أقل، ويجب البقاء خلف المركبة التي أمامك. ويستمر هذا المنع على كافة الطرق بالمنطقة حتى ظهور إشارة تعلن انتهاء المنطقة أو تغيير قواعد التجاوز.', 'images/signs/zone_signs/ZC35T Einde zone verboden inhalen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC35T-v1', 'Einde zone verboden inhalen', 'End of no overtaking zone', 'Fin de zone d''interdiction de dépasser', 'نهاية منطقة ممنوع التجاوز', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar inhalen tussen voertuigen verboden was. Vanaf dit punt geldt het inhaalverbod van de zone niet meer, en is inhalen weer toegestaan volgens de algemene verkeersregels en afhankelijk van de staat van de weg en andere verkeersborden.', 'This traffic sign indicates the end of the zone where overtaking between vehicles was prohibited. From this point onwards, the overtaking prohibition of the zone ends, and overtaking is allowed again according to the general traffic rules and depending on the road conditions and other traffic signs.', 'Ce panneau de signalisation indique la fin de la zone où le dépassement entre véhicules était interdit. À partir de ce point, l''interdiction de dépasser de la zone prend fin, et le dépassement est à nouveau autorisé selon les règles générales de circulation et en fonction de l''état de la route et des autres panneaux de signalisation.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي يمنع فيها التجاوز بين المركبات. ومن الآن فصاعدا، ينتهي منع التجاوز في المنطقة، ويسمح بالتجاوز مرة أخرى وفقا لقواعد المرور العامة وحسب ظروف الطريق والعلامات المرورية الأخرى.', 'assets/signs/zoneborden/ZC35T Einde zone verboden inhalen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC43', 'Zone met 50 km snelheidsbeperking', '50 km/h speed limit zone', 'Zone de limitation de vitesse à 50 km/h', 'منطقة تحديد السرعة 50 كم/س', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar de maximumsnelheid 50 kilometer per uur is. Binnen deze zone mag deze snelheid onder geen enkele omstandigheid worden overschreden, en deze beperking geldt voor alle wegen in de zone totdat een bord het einde van de zone aangeeft of de maximumsnelheid wijzigt.', 'This traffic sign indicates the beginning of a zone where the maximum speed is limited to 50 kilometers per hour. Within this zone, this speed may not be exceeded under any circumstances, and this limit applies to all roads in the zone until a sign announces the end of the zone or changes the maximum speed.', 'Ce panneau de signalisation indique le début d''une zone où la vitesse maximale est limitée à 50 kilomètres par heure. Dans cette zone, cette vitesse ne peut être dépassée en aucune circonstance, et cette limite s''applique à toutes les routes de la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie la vitesse maximale.', 'تشير إشارة المرور هذه إلى بداية منطقة تقتصر فيها السرعة القصوى على 50 كيلومترًا في الساعة. داخل هذه المنطقة لا يجوز تجاوز هذه السرعة تحت أي ظرف من الظروف، وينطبق هذا الحد على جميع الطرق في المنطقة حتى إشارة تعلن نهاية المنطقة أو تغيير السرعة القصوى.', 'images/signs/zone_signs/ZC43 Zone met 50 km snelheidsbeperking.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZC45', 'Einde zone met 50 km snelheidsbeperking', 'End of 50 km/h speed limit zone', 'Fin de zone de limitation de vitesse à 50 km/h', 'نهاية منطقة تحديد السرعة 50 كم/س', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar de maximumsnelheid 50 kilometer per uur was. Vanaf dit punt geldt deze specifieke snelheidsbeperking niet meer, en wordt de algemene maximumsnelheid voor de weg toegepast afhankelijk van het type en de locatie, tenzij een ander verkeersbord een andere snelheid aangeeft.', 'This traffic sign indicates the end of the zone where the maximum speed was 50 kilometers per hour. From this point onwards, this specific speed limit ends, and the general maximum speed for the road applies depending on its type and location, unless another traffic sign specifies a different speed.', 'Ce panneau de signalisation indique la fin de la zone où la vitesse maximale était de 50 kilomètres par heure. À partir de ce point, cette limitation de vitesse spécifique prend fin, et la vitesse maximale générale pour la route s''applique selon son type et son emplacement, sauf si un autre panneau de signalisation indique une vitesse différente.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي كانت السرعة القصوى فيها 50 كيلومتراً في الساعة. ومن الآن فصاعداً ينتهي هذا الحد الأقصى للسرعة المحددة، وتطبق السرعة القصوى العامة للطريق حسب نوعه وموقعه، ما لم تحدد علامة مرورية أخرى سرعة مختلفة.', 'images/signs/zone_signs/ZC45 Einde zone met 50 km snelheidsbeperking.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE1', 'Einde zone parkeerverbod', 'End of no parking zone', 'Fin de zone d''interdiction de stationnement', 'نهاية منطقة ممنوع وقوف السيارات', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar parkeren verboden was. Vanaf dit punt geldt het parkeerverbod van de zone niet meer, en worden de algemene parkeerregels toegepast volgens de verkeersborden en andere aanwezige markeringen ter plaatse.', 'This traffic sign indicates the end of the zone where parking was prohibited. From this point onwards, the parking prohibition of the zone ends, and the general parking rules apply according to the road signs and other markings present in the area.', 'Ce panneau de signalisation indique la fin de la zone où le stationnement était interdit. À partir de ce point, l''interdiction de stationnement de la zone prend fin, et les règles générales de stationnement s''appliquent selon les panneaux de signalisation et autres marquages présents sur les lieux.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي يمنع فيها وقوف السيارات. ومن الآن فصاعدا، ينتهي حظر الوقوف في المنطقة، وتطبق القواعد العامة للوقوف وفقا لعلامات الطريق والعلامات الأخرى الموجودة في المنطقة.', 'images/signs/zone_signs/ZE1 Einde zone parkeerverbod.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE1-v1', 'Zone parkeerverbod', 'No parking zone', 'Zone d''interdiction de stationnement', 'لا منطقة وقوف السيارات', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar parkeren volledig verboden is. Binnen deze zone is het niet toegestaan om een voertuig te parkeren of achter te laten op de weg of aan de zijkanten ervan, voor korte of lange tijd. Dit verbod geldt voor alle straten in de zone en blijft van kracht totdat een bord het einde van de zone aangeeft of de parkeerregels wijzigt.', 'This traffic sign indicates the beginning of a zone where parking is completely prohibited. Within this zone, it is not allowed to park or leave a vehicle on the road or on its sides, for a short or long period. This prohibition applies to all streets in the zone and remains in effect until a sign announces the end of the zone or changes the parking rule.', 'Ce panneau de signalisation indique le début d''une zone où le stationnement est totalement interdit. Dans cette zone, il n''est pas permis de garer ou de laisser un véhicule sur la route ou sur ses côtés, pour une courte ou longue période. Cette interdiction s''applique à toutes les rues de la zone et reste en vigueur jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie la règle de stationnement.', 'تشير هذه العلامة المرورية إلى بداية المنطقة التي يُمنع فيها وقوف السيارات بشكل كامل. لا يجوز داخل هذه المنطقة ركن المركبة أو تركها على الطريق أو على جوانبه لفترة قصيرة أو طويلة. وينطبق هذا المنع على جميع شوارع المنطقة ويظل ساري المفعول حتى إشارة تعلن نهاية المنطقة أو تغيير قاعدة وقوف السيارات.', 'assets/signs/zoneborden/ZE1 Zone parkeerverbod.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE9a', 'Einde zone parkeren beperkt in tijd, parkeerschijf verplicht', 'End of zone parking limited in time, parking disc required', 'Fin de zone de stationnement limité dans le temps, disque de stationnement obligatoire', 'وقوف السيارات في نهاية المنطقة محدود في الوقت المناسب، ويلزم وجود قرص وقوف السيارات', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar parkeren beperkt was tot bewoners die een vergunning of bewonerskaart hebben. Vanaf dit punt gelden de beperkingen voor bewoners niet meer, en worden de algemene parkeerregels toegepast volgens de verkeersborden of andere geldende aanwijzingen ter plaatse.', 'This traffic sign indicates the end of the zone where parking was restricted to residents only with a permit or residential card. From this point onwards, the restrictions for residents end, and the general parking rules apply according to the road signs or other applicable instructions in the area.', 'Ce panneau de signalisation indique la fin de la zone où le stationnement était réservé aux résidents munis d''un permis ou d''une carte résidentielle. À partir de ce point, les restrictions pour les résidents prennent fin, et les règles générales de stationnement s''appliquent selon les panneaux de signalisation ou autres instructions applicables sur les lieux.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي كان الوقوف فيها مقصوراً على المقيمين الذين يحملون تصريحاً أو بطاقة سكن فقط. ومن الآن فصاعدا، تنتهي القيود المفروضة على السكان، وتطبق القواعد العامة لوقوف السيارات وفقا لعلامات الطريق أو غيرها من التعليمات المعمول بها في المنطقة.', 'images/signs/zone_signs/ZE9a parkeerschijf Einde zone parkeren beperkt in tijd, parkeerschijf verplicht.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE9a-v1', 'Zone parkeren beperkt in tijd, parkeerschijf verplicht', 'Zone parking limited in time, parking disc required', 'Zone de stationnement limité dans le temps, disque de stationnement obligatoire', 'منطقة وقوف السيارات محدودة في الوقت المناسب، قرص وقوف السيارات مطلوب', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar parkeren alleen is toegestaan voor bewoners die een vergunning of erkende bewonerskaart hebben. Binnen deze zone is het parkeren van andere voertuigen zonder vergunning verboden, ook al zijn er lege plaatsen beschikbaar. Deze regel blijft van kracht in de hele zone totdat een bord het einde van de zone aangeeft of de parkeervoorwaarden wijzigt.', 'This traffic sign indicates the beginning of a parking zone where parking is only allowed for residents with an approved permit or residential card. Within this zone, parking of other unauthorized vehicles is prohibited, even if there are vacant spaces available. This rule continues throughout the zone until a sign announces the end of the zone or changes the parking conditions.', 'Ce panneau de signalisation indique le début d''une zone de stationnement où le stationnement n''est autorisé qu''aux résidents munis d''un permis ou d''une carte résidentielle approuvée. Dans cette zone, le stationnement des autres véhicules non autorisés est interdit, même s''il y a des places disponibles. Cette règle s''applique dans toute la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie les conditions de stationnement.', 'تشير هذه العلامة المرورية إلى بداية منطقة وقوف السيارات حيث يُسمح بوقوف السيارات فقط للمقيمين الذين يحملون تصريحًا أو بطاقة سكن معتمدة. داخل هذه المنطقة، يحظر وقوف المركبات الأخرى غير المصرح بها، حتى لو كانت هناك أماكن شاغرة متاحة. وتستمر هذه القاعدة في جميع أنحاء المنطقة حتى تعلن علامة عن نهاية المنطقة أو تغير ظروف وقوف السيارات.', 'assets/signs/zoneborden/ZE9a parkeerschijf Zone parkeren beperkt in tijd, parkeerschijf verplicht.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE9a-v2', 'Zone parkeren uitsluitend voor auto''s', 'Zone parking for cars only', 'Zone de stationnement réservée aux voitures', 'منطقة انتظار السيارات للسيارات فقط', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar parkeren uitsluitend is toegestaan voor auto''s, exclusief motorfietsen, vrachtwagens of andere voertuigen. Deze regel geldt voor alle parkeerplaatsen binnen de grenzen van de zone en blijft van kracht totdat een bord het einde van de zone aangeeft of de parkeervoorwaarden wijzigt.', 'This traffic sign indicates the beginning of a zone where parking is only allowed for cars, excluding motorcycles, trucks, or other vehicles. This rule applies to all parking spaces within the zone boundaries and remains in effect until a sign announces the end of the zone or changes the parking conditions.', 'Ce panneau de signalisation indique le début d''une zone où le stationnement n''est autorisé que pour les voitures, à l''exclusion des motos, camions ou autres véhicules. Cette règle s''applique à tous les emplacements de stationnement dans les limites de la zone et reste en vigueur jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie les conditions de stationnement.', 'تشير إشارة المرور هذه إلى بداية المنطقة التي يُسمح فيها بوقوف السيارات فقط، باستثناء الدراجات النارية أو الشاحنات أو المركبات الأخرى. تنطبق هذه القاعدة على جميع أماكن وقوف السيارات داخل حدود المنطقة وتظل سارية المفعول حتى إشارة تعلن عن نهاية المنطقة أو تغيير شروط وقوف السيارات.', 'assets/signs/zoneborden/ZE9a Zone parkeren uitsluitend voor auto''s.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE9aT', 'Einde zone parkeren uitsluitend voor auto''s', 'End of paid parking zone for cars only', 'Fin de zone de stationnement payant réservée aux voitures', 'نهاية منطقة وقوف السيارات مدفوعة الأجر للسيارات فقط', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar betaald parkeren verplicht was en die uitsluitend bestemd was voor auto''s. Vanaf dit punt gelden de betalende parkeerregels van deze zone niet meer, en worden de algemene parkeerregels toegepast volgens de verkeersborden of andere aanwijzingen op de weg.', 'This traffic sign indicates the end of the zone where paid parking was required and was designated for cars only. From this point onwards, the paid parking rules of this zone end, and the general parking rules apply according to the traffic signs or other instructions on the road.', 'Ce panneau de signalisation indique la fin de la zone où le stationnement payant était obligatoire et réservée aux voitures uniquement. À partir de ce point, les règles de stationnement payant de cette zone prennent fin, et les règles générales de stationnement s''appliquent selon les panneaux de signalisation ou autres instructions sur la route.', 'تشير هذه الشاخصة المرورية إلى نهاية المنطقة التي يلزم فيها ركن السيارات مدفوعة الأجر والتي كانت مخصصة للسيارات فقط. ومن الآن فصاعداً تنتهي قواعد المواقف المدفوعة الأجر في هذه المنطقة، وتطبق القواعد العامة للوقوف وفقاً لإشارات المرور أو غيرها من التعليمات على الطريق.', 'images/signs/zone_signs/ZE9aT Einde zone parkeren uitsluitend voor auto''s.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE9aT-v1', 'Zone parkeren uitsluitend voor auto''s', 'Paid parking zone for cars only', 'Zone de stationnement payant réservée aux voitures', 'منطقة وقوف السيارات مدفوعة الأجر للسيارات فقط', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een betalende parkeerzone aan die uitsluitend bestemd is voor auto''s. Binnen deze zone is parkeren toegestaan op voorwaarde dat de vereiste kosten worden betaald volgens het geldende systeem, zoals een betaalautomaat, app of ticket. Andere voertuigen dan auto''s mogen hier niet parkeren. Deze regel geldt in alle straten van de zone totdat een bord het einde van de zone aangeeft of de parkeervoorwaarden wijzigt.', 'This traffic sign indicates the beginning of a paid parking zone designated for cars only. Within this zone, parking is allowed provided that the required fees are paid according to the applicable system such as a payment machine, app, or ticket. Vehicles other than cars are not allowed to park here. This rule continues in all streets of the zone until a sign announces the end of the zone or changes the parking conditions.', 'Ce panneau de signalisation indique le début d''une zone de stationnement payant réservée aux voitures uniquement. Dans cette zone, le stationnement est autorisé à condition de payer les frais requis selon le système en vigueur comme un horodateur, une application ou un ticket. Les véhicules autres que les voitures ne sont pas autorisés à stationner ici. Cette règle s''applique dans toutes les rues de la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie les conditions de stationnement.', 'تشير هذه العلامة المرورية إلى بداية منطقة ركن السيارات مدفوعة الأجر المخصصة للسيارات فقط. يُسمح داخل هذه المنطقة بوقوف السيارات على أن يتم دفع الرسوم المطلوبة حسب النظام المتبع مثل ماكينة الدفع أو التطبيق أو التذكرة. لا يُسمح للمركبات غير السيارات بالوقوف هنا. وتستمر هذه القاعدة في جميع شوارع المنطقة حتى ظهور علامة تعلن انتهاء المنطقة أو تغيير شروط الوقوف.', 'assets/signs/zoneborden/ZE9aT Zone parkeren uitsluitend voor auto''s.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE9T', 'Einde zone parkeren voor voertuigen met 3.5t uitzondering', 'End of zone parking for vehicles up to 3.5t maximum', 'Fin de zone de stationnement pour véhicules jusqu''à 3,5t maximum', 'نهاية منطقة ركن السيارات للمركبات التي يصل وزنها إلى 3.5 طن كحد أقصى', NULL, NULL, NULL, NULL, 'Dit bord geeft het einde aan van de zone waar parkeren alleen was toegestaan voor voertuigen met een maximaal toegestaan gewicht van 3,5 ton. Vanaf dit punt gelden de speciale parkeervoorwaarden van deze zone niet meer, en worden de algemene parkeerregels toegepast volgens de verkeersborden en andere aanwezige markeringen.', 'This traffic sign indicates the end of the zone where parking was only allowed for vehicles whose total permitted weight does not exceed 3.5 tons. From this point onwards, the special parking conditions of this zone end, and the general parking rules apply according to the road signs and other markings present in the area.', 'Ce panneau de signalisation indique la fin de la zone où le stationnement n''était autorisé que pour les véhicules dont le poids total autorisé ne dépasse pas 3,5 tonnes. À partir de ce point, les conditions de stationnement spéciales de cette zone prennent fin, et les règles générales de stationnement s''appliquent selon les panneaux de signalisation et autres marquages présents sur les lieux.', 'تشير هذه العلامة المرورية إلى نهاية المنطقة التي يسمح فيها بالوقوف فقط للمركبات التي لا يتجاوز وزنها الإجمالي المسموح به 3.5 طن. ومن هنا فصاعداً تنتهي الشروط الخاصة للوقوف في هذه المنطقة، وتطبق القواعد العامة للوقوف وفقاً لعلامات الطريق والعلامات الأخرى الموجودة في المنطقة.', 'images/signs/zone_signs/ZE9T Einde zone parkeren voor voertuigen met 3.5t uitzondering.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZE9T-v1', 'Zone parkeren voor voertuigen met 3.5t uitzondering', 'Zone parking for vehicles up to 3.5t maximum', 'Zone de stationnement pour véhicules jusqu''à 3,5t maximum', 'منطقة ركن السيارات للمركبات التي يصل وزنها إلى 3.5 طن كحد أقصى', NULL, NULL, NULL, NULL, 'Dit bord geeft het begin van een zone aan waar parkeren alleen is toegestaan voor voertuigen met een maximaal toegestaan gewicht van 3,5 ton. Binnen deze zone is het parkeren van voertuigen zwaarder dan dit gewicht verboden, ook al is er geen apart verbodsbord. Deze regel geldt voor alle parkeerplaatsen binnen de zone totdat een bord het einde van de zone aangeeft of de parkeervoorwaarden wijzigt.', 'This traffic sign indicates the beginning of a zone where parking is only allowed for vehicles whose total permitted weight does not exceed 3.5 tons. Within this zone, parking of vehicles heavier than this weight is prohibited, even if no separate prohibition sign appears. This rule applies to all parking spaces within the zone until a sign announces the end of the zone or changes the parking conditions.', 'Ce panneau de signalisation indique le début d''une zone où le stationnement n''est autorisé que pour les véhicules dont le poids total autorisé ne dépasse pas 3,5 tonnes. Dans cette zone, le stationnement des véhicules plus lourds que ce poids est interdit, même si aucun panneau d''interdiction séparé n''apparaît. Cette règle s''applique à tous les emplacements de stationnement dans la zone jusqu''à ce qu''un panneau annonce la fin de la zone ou modifie les conditions de stationnement.', 'تشير هذه العلامة المرورية إلى بداية المنطقة التي يُسمح فيها بوقوف السيارات فقط للمركبات التي لا يتجاوز وزنها الإجمالي المسموح به 3.5 طن. داخل هذه المنطقة، يُمنع وقوف المركبات الأثقل من هذا الوزن، حتى لو لم تظهر علامة منع منفصلة. تنطبق هذه القاعدة على كافة أماكن ركن السيارات داخل المنطقة حتى ظهور علامة تعلن انتهاء المنطقة أو تغيير شروط ركن السيارات.', 'assets/signs/zoneborden/ZE9T Zone parkeren voor voertuigen met 3.5t uitzondering.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='Z'), 'ZONE', 'Einde ZONE Fietsstraat', 'End of bicycle street zone', 'Fin de zone rue cyclable', 'نهاية منطقة شارع الدراجات الهوائية', 'Geeft het begin aan van een zone waarin specifieke verkeersregels gelden.', NULL, NULL, NULL, 'Dit bord geeft het einde aan van de fietsstraatzone waar fietsen speciale voorrang kregen. Vanaf dit punt gelden de normale verkeersregels weer, zonder speciale voorrang voor fietsers, tenzij een ander verkeersbord een andere situatie aangeeft.', 'This traffic sign indicates the end of the bicycle street zone where bicycles were given special priority. From this point onwards, the special rules for this zone end and the general traffic rules apply, without giving special preference to bicycles, unless another traffic sign specifies a different situation.', 'Ce panneau de signalisation indique la fin de la zone de rue cyclable où les vélos avaient une priorité spéciale. À partir de ce point, les règles spéciales de cette zone prennent fin et les règles générales de circulation s''appliquent, sans donner de préférence spéciale aux vélos, sauf si un autre panneau de signalisation indique une situation différente.', 'تشير إشارة المرور هذه إلى نهاية منطقة شارع الدراجات حيث تم إعطاء الدراجات أولوية خاصة. ومن الآن فصاعدا، تنتهي القواعد الخاصة بهذه المنطقة وتطبق القواعد العامة للمرور، دون إعطاء أفضلية خاصة للدراجات، ما لم تحدد إشارة مرور أخرى موقفا مختلفا.', 'assets/signs/zoneborden/ZONE F113 Einde ZONE Fietsstraat.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F31', 'Wegwijzer autostrade.', 'Wegwijzer autostrade.', 'Wegwijzer autostrade.', 'لوحة إرشادية للطريق السريع', NULL, NULL, NULL, NULL, 'Wegwijzer autostrade.', 'Wegwijzer autostrade.', 'Wegwijzer autostrade.', 'لوحة إرشادية توجه إلى الطريق السريع.', 'images/signs/direction_signs/F31 Wegwijzer autostrade.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F23d', 'Nummer van een ringweg', 'Ring road number', 'Numéro de route périphérique', 'علامة طريق حولي', 'Nummer van een ring.', NULL, NULL, NULL, 'Dit verkeersbord geeft een ringweg aan die rond een stad of regio loopt. Het wordt meestal gebruikt om het rijden door het stadscentrum te vermijden en verkeersopstoppingen te verminderen.', 'This traffic sign indicates a ring road that surrounds a city or area. It is mostly used to avoid driving through the city center to reduce traffic congestion.', 'Ce panneau de signalisation indique une route périphérique qui entoure une ville ou une région. Il est principalement utilisé pour éviter de traverser le centre-ville afin de réduire les embouteillages.', 'تشير إشارة المرور هذه إلى الطريق الدائري الذي يحيط بالمدينة أو المنطقة. يتم استخدامه في الغالب لتجنب القيادة عبر وسط المدينة لتقليل الازدحام المروري.', 'assets/signs/aanwijzingsborden/F23d Nummer van een ringweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F23c', 'Nummer van een internationale weg', 'International road number', 'Numéro de route internationale', 'علامة طريق دولي', 'Nummer van een internationale weg.', NULL, NULL, NULL, 'Dit verkeersbord geeft aan dat je op een Europese internationale weg rijdt. Het is een netwerk van wegen die de landen van de Europese Unie verbinden en wordt gebruikt voor langeafstandsreizen.', 'This traffic sign indicates that you are on an international European road. It is a network of roads connecting European Union countries and is used for long-distance travel.', 'Ce panneau de signalisation indique que vous êtes sur une route européenne internationale. C''est un réseau de routes reliant les pays de l''Union européenne et est utilisé pour les voyages longue distance.', 'تشير إشارة المرور هذه إلى أنك على طريق أوروبي دولي. وهي عبارة عن شبكة من الطرق التي تربط دول الاتحاد الأوروبي وتستخدم للسفر لمسافات طويلة.', 'assets/signs/aanwijzingsborden/F23c Nummer van een internationale weg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F23b', 'Nummer van een autosnelweg', 'Highway number', 'Numéro d''autoroute', 'علامة رقم طريق سريع', 'Nummer van een autosnelweg.', NULL, NULL, NULL, 'Dit bord geeft aan dat je op een autosnelweg rijdt die bestemd is voor voertuigen met hoge snelheid. Deze weg is meestal omheind en heeft geen kruispunten, maar wel op- en afritten.', 'This sign indicates that you are on a highway designated for high-speed vehicles. This road is usually fenced and has no intersections but has on and off ramps.', 'Ce panneau indique que vous êtes sur une autoroute réservée aux véhicules à grande vitesse. Cette route est généralement clôturée et n''a pas de carrefours mais possède des bretelles d''entrée et de sortie.', 'تدل على أنك على طريق سريع مخصص للمركبات ذات السرعة العالية، غالباً ما يكون هذا الطريق محاطاً بسياج ولا يحتوي على تقاطعات ولكن يحتوي على مسارات وتحويلات.', 'assets/signs/aanwijzingsborden/F23b Nummer van een autosnelweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F23a', 'Nummer van een gewone weg', 'Regular road number', 'Numéro de route ordinaire', 'علامة رقم طريق عادي', 'Nummer van een gewone weg.', NULL, NULL, NULL, 'Dit bord geeft het nummer van een gewone weg (niet-snelweg) aan. Dit type weg wordt vaak gebruikt om steden en dorpen te verbinden en wordt gekenmerkt door een blauwe kleur.', 'This sign indicates the number of a regular road (non-highway). This type of road is often used to connect cities and villages and is characterized by a blue color.', 'Ce panneau indique le numéro d''une route ordinaire (non-autoroute). Ce type de route est souvent utilisé pour relier les villes et les villages et se caractérise par une couleur bleue.', 'تشير هذه العلامة إلى رقم الطريق العادي (غير السريع)، يستخدم هذا النوع من الطرق غالباً للربط بين المدن والقرى، ويتميز بلون أزرق.', 'assets/signs/aanwijzingsborden/F23a Nummer van een gewone weg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F21', 'Rechts of links voorbijrijden toegelaten', 'Passing on both sides allowed', 'Passage à droite ou à gauche autorisé', 'المسار بالاتجاهين مسموح', 'Rechts of links voorbijrijden is toegelaten.', 'Passing on the right or left is allowed.', 'Passage à droite ou à gauche autorisé.', 'التجاوز على اليمين أو اليسار مسموح.', 'Dit bord geeft aan dat de bestuurder zowel links als rechts mag passeren vanaf dit punt. Het wordt vaak geplaatst bij kruispunten om de beschikbare opties voor de bestuurder te verduidelijken bij het kiezen van een richting.', 'This sign indicates that the driver can pass either left or right from this point. It is often placed at intersections to clarify the available options for the driver when choosing a direction.', 'Ce panneau indique que le conducteur peut passer à gauche ou à droite à partir de ce point. Il est souvent placé aux carrefours pour clarifier les options disponibles pour le conducteur lors du choix d''une direction.', 'تشير هذه العلامة إلى أن السائق يمكنه المرور يسارًا أو يمينًا من هذه النقطة. وغالباً ما يتم وضعها عند التقاطعات لتوضيح الخيارات المتاحة للسائق عند اختيار الاتجاه.', 'images/signs/direction_signs/F21 Rechts of links voorbijrijden toegelaten.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F19', 'Eenrichtingsverkeer', 'One-way traffic', 'Sens unique', 'طريق باتجاه واحد', 'Openbare weg met eenrichtingsverkeer.', 'One-way street.', 'Rue à sens unique.', 'شارع باتجاه واحد.', 'Dit bord geeft aan dat de weg uitsluitend bestemd is voor verkeer in één richting. Rijden tegen de richting van de pijl is verboden om ongelukken te voorkomen. Dit bord wordt vaak gebruikt in smalle straten of woonwijken om een vlotte doorstroming en verkeersveiligheid te garanderen.', 'This sign indicates that the road is designated for one-way traffic only. Driving against the direction of the arrow is prohibited to avoid accidents. This sign is commonly used in narrow streets or residential areas to ensure smooth traffic flow and road safety.', 'Ce panneau indique que la route est réservée à la circulation à sens unique. Conduire dans le sens contraire de la flèche est interdit pour éviter les accidents. Ce panneau est généralement utilisé dans les rues étroites ou les quartiers résidentiels pour assurer une circulation fluide et la sécurité routière.', 'تشير هذه الإشارة إلى أن الطريق مخصص لحركة المرور في اتجاه واحد فقط. يحظر القيادة عكس اتجاه السهم لتجنب وقوع الحوادث. تُستخدم هذه العلامة بشكل شائع في الشوارع الضيقة أو المناطق السكنية لضمان التدفق السلس لحركة المرور والسلامة على الطرق.', 'images/signs/direction_signs/F19 Eenrichtingsverkeer.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F14', 'Opstelvak voor fietsers', 'Advance stop line for cyclists', 'Zone avancée pour cyclistes', 'خط التوقف المتقدم لراكبي الدراجات', NULL, NULL, NULL, NULL, 'Dit bord geeft een opstelvak aan dat uitsluitend is bestemd voor fietsers. Auto''s moeten stoppen bij de eerste stoplijn om te voorkomen dat fietsers worden gehinderd bij kruispunten met dit bord.', 'This sign indicates an advance stop box exclusively for cyclists. Cars must stop at the first stop line to avoid obstructing cyclists at intersections with this sign.', 'Ce panneau indique une zone avancée exclusivement réservée aux cyclistes. Les voitures doivent s''arrêter à la première ligne d''arrêt pour éviter de gêner les cyclistes aux carrefours avec ce panneau.', 'تشير هذه العلامة إلى وجود صندوق توقف متقدم مخصص لراكبي الدراجات فقط. يجب على السيارات التوقف عند خط التوقف الأول لتجنب عرقلة راكبي الدراجات عند التقاطعات التي تحمل هذه العلامة.', 'images/signs/direction_signs/F14 Opstelvak voor fietsers en bromfietsen.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F13', 'Rijstrook keuze', 'Lane choice by direction', 'Choix de voie selon la direction', 'اختيار المسار حسب الاتجاه', 'Verkeersbord dat pijlen op de rijbaan aankondigt en de keuze van een rijstrook voorschrijft.', NULL, NULL, NULL, 'Dit bord geeft aan dat er meerdere rijstroken zijn en dat de bestuurder tijdig de juiste rijstrook moet kiezen afhankelijk van de gewenste richting (links of rechtdoor). Dit bord wordt vaak gebruikt voor kruispunten of snelwegafritten en beide richtingen zijn toegestaan.', 'This sign indicates that there are multiple lanes and the driver must choose the appropriate lane early depending on the intended direction (left or straight ahead). This sign is often used before intersections or highway exits and both directions are allowed.', 'Ce panneau indique qu''il y a plusieurs voies et que le conducteur doit choisir la voie appropriée à l''avance selon la direction souhaitée (gauche ou tout droit). Ce panneau est souvent utilisé avant les carrefours ou les sorties d''autoroute et les deux directions sont autorisées.', 'تشير هذه الإشارة إلى وجود مسارات متعددة ويجب على السائق اختيار المسار المناسب مبكراً حسب الاتجاه المقصود (يساراً أو أماماً مستقيماً). تستخدم هذه الإشارة غالباً قبل التقاطعات أو مخارج الطرق السريعة ومسموح بالاتجاهين.', 'images/signs/direction_signs/F13 Rijstrook keuze.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F12b', 'Einde woonerf', 'End of residential area', 'Fin de zone résidentielle', 'نهاية الحي السكني', 'Einde van een woonerf of erf.', 'End of residential area (woonerf).', 'Fin de zone résidentielle (woonerf).', 'نهاية المنطقة السكنية (woonerf).', 'Dit bord geeft het einde van een woonerf aan. Vanaf dit punt gelden de normale verkeersregels en snelheidslimieten weer volgens de wet of andere verkeersborden. Voetgangers hebben geen speciale voorrang meer.', 'This sign indicates the end of a residential area (woonerf). From this point, normal traffic rules and speed limits apply again according to the law or other traffic signs. Pedestrians no longer have special priority.', 'Ce panneau indique la fin d''une zone résidentielle. À partir de ce point, les règles de circulation et les limites de vitesse normales s''appliquent à nouveau selon la loi ou d''autres panneaux de signalisation. Les piétons n''ont plus de priorité spéciale.', 'تشير هذه العلامة إلى نهاية المنطقة السكنية (woonerf). ومن هذه النقطة، يتم تطبيق قواعد المرور العادية وحدود السرعة مرة أخرى وفقًا للقانون أو إشارات المرور الأخرى. لم يعد للمشاة أولوية خاصة.', 'assets/signs/aanwijzingsborden/F12b Einde van een woonerf of van een erf.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F12a', 'Begin woonerf', 'Start of residential area', 'Début de zone résidentielle', 'بداية الحي السكني', 'Begin van een woonerf of erf.', 'Start of residential area (woonerf).', 'Début de zone résidentielle (woonerf).', 'بداية المنطقة السكنية (woonerf).', 'Dit bord geeft het begin van een woonerf aan. Voetgangers hebben hier voorrang en de maximumsnelheid is 20 km/u. Kinderen mogen op straat spelen, dus bestuurders moeten extra voorzichtig zijn en rustig rijden.', 'This sign indicates the start of a residential area (woonerf). Pedestrians have priority here and the maximum speed is 20 km/h. Children are allowed to play on the street, so drivers must be extra careful and drive calmly.', 'Ce panneau indique le début d''une zone résidentielle. Les piétons ont la priorité ici et la vitesse maximale est de 20 km/h. Les enfants sont autorisés à jouer dans la rue, les conducteurs doivent donc être très prudents et conduire calmement.', 'تشير هذه العلامة إلى بداية منطقة سكنية (woonerf). الأولوية هنا للمشاة والسرعة القصوى هي 20 كم/ساعة. يُسمح للأطفال باللعب في الشارع، لذا يجب على السائقين توخي الحذر الشديد والقيادة بهدوء.', 'assets/signs/aanwijzingsborden/F12a Begin van een woonerf of van een erf.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F11', 'Einde autoweg', 'End of expressway', 'Fin de route pour automobiles', 'نهاية الطريق المخصص للمركبات', 'Einde autoweg.', 'End of expressway.', 'Fin de route pour automobiles.', 'نهاية طريق السيارات.', 'Dit bord geeft het einde van een autoweg aan. Vanaf dit punt gelden de speciale autoweg-regels niet meer en keren de normale verkeersregels terug die gelden op gewone wegen.', 'This sign indicates the end of an expressway. From this point, the special expressway rules no longer apply and normal traffic rules for regular roads return.', 'Ce panneau indique la fin d''une route pour automobiles. À partir de ce point, les règles spéciales de la route pour automobiles ne s''appliquent plus et les règles de circulation normales pour les routes ordinaires reprennent.', 'تشير هذه العلامة المرورية إلى انتهاء الطريق المخصص للمركبات، مما يعني انتهاء جميع القواعد الخاصة به، والعودة إلى القواعد العامة للسير المعمول بها على الطرق العادية.', 'images/signs/direction_signs/F11 Einde van de autoweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F9', 'Autoweg', 'Expressway', 'Route pour automobiles', 'طريق مخصص للمركبات', 'Geeft aan dat de weg doodloopt.', 'Start of expressway.', 'Début de route pour automobiles.', 'بداية طريق السيارات.', 'Dit bord geeft een autoweg aan, een weg uitsluitend bestemd voor gemotoriseerde voertuigen. Voetgangers en fietsers zijn niet toegestaan. De standaard snelheidslimiet is 70 km/u tenzij anders aangegeven.', 'This sign indicates an expressway, a road exclusively for motorized vehicles. Pedestrians and cyclists are not allowed. The standard speed limit is 70 km/h unless otherwise indicated.', 'Ce panneau indique une route pour automobiles, une route exclusivement réservée aux véhicules motorisés. Les piétons et les cyclistes ne sont pas autorisés. La limite de vitesse standard est de 70 km/h sauf indication contraire.', 'تشير هذه الشاخصة إلى طريق سريع، طريق خاص بالمركبات الآلية. لا يسمح للمشاة وراكبي الدراجات. الحد الأقصى للسرعة هو 70 كم/ساعة ما لم يُنص على خلاف ذلك.', 'images/signs/direction_signs/F9 Autoweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F8', 'Tunnel', 'Start of tunnel', 'Début de tunnel', 'بداية النفق', NULL, NULL, NULL, NULL, 'Dit bord geeft aan dat je een tunnel nadert, vaak in combinatie met snelheids- en verlichtingswijzigingen. Je moet je koplampen inschakelen en inhalen, parkeren en stoppen vermijden, want dit is verboden in de tunnel.', 'This sign indicates that you are about to enter a tunnel, often used with speed and lighting changes. You must turn on your headlights and avoid overtaking, parking and stopping as these are prohibited inside the tunnel.', 'Ce panneau indique que vous êtes sur le point d''entrer dans un tunnel, souvent utilisé avec des changements de vitesse et d''éclairage. Vous devez allumer vos phares et éviter de dépasser, de stationner et de vous arrêter car cela est interdit dans le tunnel.', 'تشير هذه العلامة إلى أنك على وشك الدخول إلى نفق، وغالبًا ما تستخدم مع تغييرات السرعة والإضاءة. يجب عليك تشغيل المصابيح الأمامية وتجنب التجاوز والوقوف والتوقف لأنها محظورة داخل النفق.', 'images/signs/direction_signs/F8 Tunnel.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F7', 'Einde autosnelweg', 'End of motorway', 'Fin d''autoroute', 'نهاية الطريق السريع', 'Geeft het einde van een autoweg aan.', 'End of motorway.', 'Fin d''autoroute.', 'نهاية الطريق السريع.', 'Dit bord geeft het einde van de autosnelweg aan. Vanaf hier rijd je op een gewone weg, binnen of buiten de bebouwde kom. Alle speciale regels van de autosnelweg vervallen en de regels gelden afhankelijk van het wegtype en de aanwezige borden.', 'This sign indicates the end of the motorway. From this point, you are on a regular road, either inside or outside a built-up area. All motorway rules are cancelled, and rules apply according to the road type and signs present.', 'Ce panneau indique la fin de l''autoroute. À partir de ce point, vous circulez sur une route ordinaire, en agglomération ou hors agglomération. Toutes les règles spéciales de l''autoroute sont annulées et les règles s''appliquent selon le type de route et les panneaux présents.', 'تشير هذه العلامة إلى نهاية الطريق السريع. من هذه النقطة، أنت على طريق منتظم، سواء داخل أو خارج المنطقة المبنية. يتم إلغاء جميع قواعد الطريق السريع، ويتم تطبيق القواعد وفقًا لنوع الطريق والعلامات الموجودة.', 'images/signs/direction_signs/F7 Einde autosnelweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F5', 'Autosnelweg', 'Motorway', 'Autoroute', 'بداية الطريق السريع', 'Geeft het begin van een autoweg aan.', 'Start of motorway.', 'Début d''autoroute.', 'بداية الطريق السريع.', 'Dit bord geeft het begin van een autosnelweg aan. Stoppen en parkeren zijn verboden, behalve in noodgevallen. De snelheid ligt tussen 70 en 120 km/u, tenzij anders aangegeven.', 'This sign indicates the start of a motorway. Stopping and parking are prohibited except for emergencies. Speed limits range from 70 to 120 km/h, unless otherwise indicated.', 'Ce panneau indique le début d''une autoroute. L''arrêt et le stationnement sont interdits sauf en cas d''urgence. La vitesse est comprise entre 70 et 120 km/h, sauf indication contraire.', 'تشير هذه العلامة إلى بداية الطريق السريع. يمنع التوقف والوقوف إلا في حالات الطوارئ. تتراوح حدود السرعة من 70 إلى 120 كم/ساعة، ما لم يُنص على خلاف ذلك.', 'images/signs/direction_signs/F5 Autosnelweg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F3b', 'Einde van een bebouwde kom', 'End of built-up area', 'Fin d''une agglomération', 'علامة انتهاء المدينة', NULL, NULL, NULL, NULL, 'Dit bord geeft aan dat je de bebouwde kom verlaat. Vanaf hier gelden de verkeersregels voor buiten de bebouwde kom, zoals een maximumsnelheid van 70 of 90 km/u, afhankelijk van de weg en andere aanwijzingen.', 'This sign indicates that you are leaving the built-up area (residential zone). From this point, rules for outside built-up areas apply, with maximum speeds typically of 70 or 90 km/h, depending on road conditions and other signs.', 'Ce panneau indique que vous quittez l''agglomération (zone résidentielle). À partir de ce point, les règles hors agglomération s''appliquent, avec des vitesses maximales généralement de 70 ou 90 km/h, selon les conditions et la signalisation.', 'تشير هذه العلامة إلى خروجك من المنطقة السكنية. ومن هذه النقطة، تُطبق قواعد السير خارج المنطقة السكنية، بسرعات قصوى تبلغ عادةً 70 أو 90 كم/ساعة، وفقًا لظروف الطريق والعلامات الأخرى.', 'assets/signs/aanwijzingsborden/F3b Einde van een bebouwde kom.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F118-v1', 'Einde van lage emissiezone', 'End of low emission zone', 'Fin de zone à faibles émissions', 'نهاية منطقة الانبعاثات المنخفضة', NULL, NULL, NULL, NULL, 'Dit bord geeft aan dat je de milieuzone verlaat waar beperkingen golden voor voertuigen met hoge uitstoot. Na dit bord gelden weer de normale verkeersregels.', 'This sign indicates that you are now leaving the environmental zone where restrictions applied to vehicles with high emissions. After this sign, normal traffic rules apply again.', 'Ce panneau indique que vous quittez maintenant la zone environnementale où des restrictions s''appliquaient aux véhicules à fortes émissions. Après ce panneau, les règles de circulation normales s''appliquent à nouveau.', 'تشير هذه العلامة إلى أنك الآن تغادر المنطقة البيئية التي تنطبق عليها القيود على المركبات ذات الانبعاثات العالية. بعد هذه الإشارة، يتم تطبيق قواعد المرور العادية مرة أخرى.', 'assets/signs/aanwijzingsborden/F118 Einde van lage emissiezone.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F117-v1', 'Begin van lage emissiezone', 'Start of low emission zone', 'Début de zone à faibles émissions', 'بداية منطقة الانبعاثات المنخفضة', NULL, NULL, NULL, NULL, 'Dit bord geeft aan dat je een milieuzone binnenrijdt waar de uitstoot van voertuigen wordt beperkt. Alleen voertuigen die aan bepaalde milieunormen voldoen mogen hier rijden. Dit wordt vaak gebruikt in stadscentra om luchtvervuiling te verminderen.', 'This sign indicates that you are entering an environmental zone where vehicle emissions are restricted. Only vehicles that meet specific environmental standards are allowed to drive here. This is often used in city centers to reduce air pollution.', 'Ce panneau indique que vous entrez dans une zone environnementale où les émissions des véhicules sont limitées. Seuls les véhicules répondant à des normes environnementales spécifiques sont autorisés à circuler ici. Cela est souvent utilisé dans les centres-villes pour réduire la pollution atmosphérique.', 'تشير هذه العلامة إلى أنك تدخل منطقة بيئية تكون فيها انبعاثات المركبات مقيدة. يُسمح فقط للمركبات التي تستوفي معايير بيئية محددة بالقيادة هنا. وغالبا ما يستخدم هذا في مراكز المدن للحد من تلوث الهواء.', 'assets/signs/aanwijzingsborden/F117 Begin van lage emissiezone.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F113', 'Einde fietsstraat', 'End of bicycle street', 'Fin de rue cyclable', 'نهاية شارع الدراجات الهوائية', 'Fietsstraat.', NULL, NULL, NULL, 'Dit bord geeft het einde van een fietsstraat aan. Vanaf dit punt gelden de normale verkeersregels weer en hebben fietsers geen speciale voorrang meer. De regels voor gewone wegen zijn van toepassing.', 'This sign indicates the end of a bicycle street. From this point, normal traffic rules apply again and cyclists no longer have special priority. The rules for regular roads apply.', 'Ce panneau indique la fin d''une rue cyclable. À partir de ce point, les règles de circulation normales s''appliquent à nouveau et les cyclistes n''ont plus de priorité spéciale. Les règles des routes ordinaires s''appliquent.', 'تشير هذه العلامة إلى نهاية شارع الدراجات. من هذه النقطة، يتم تطبيق قواعد المرور العادية مرة أخرى ولم يعد لراكبي الدراجات أولوية خاصة. تنطبق قواعد الطرق العادية.', 'images/signs/direction_signs/F113 Einde fietsstraat.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F111', 'Fietsstraat', 'Bicycle street', 'Rue cyclable', 'شارع الدراجات الهوائية', 'Begin / Einde fietsstraat.', 'Start / End of bicycle street.', 'Début / Fin de rue cyclable.', 'بداية / نهاية شارع الدراجات.', 'Dit bord geeft een fietsstraat aan. Deze straat is primair bedoeld voor fietsers. Auto''s mogen er wel rijden, maar moeten achter de fietsers blijven en mogen niet inhalen. De maximumsnelheid is 30 km/u. De weg is vaak rood gekleurd met fietssymbolen om de prioriteit van fietsers te benadrukken.', 'This sign indicates a bicycle street. This street is primarily intended for cyclists. Cars are allowed but must stay behind cyclists and may not overtake. The maximum speed is 30 km/h. The road is often colored red with bicycle symbols to emphasize the priority of cyclists.', 'Ce panneau indique une rue cyclable. Cette rue est principalement destinée aux cyclistes. Les voitures sont autorisées mais doivent rester derrière les cyclistes et ne peuvent pas dépasser. La vitesse maximale est de 30 km/h. La route est souvent de couleur rouge avec des symboles de vélo pour souligner la priorité des cyclistes.', 'تشير هذه العلامة إلى شارع للدراجات. هذا الشارع مخصص في المقام الأول لراكبي الدراجات. يُسمح بالسيارات ولكن يجب أن تبقى خلف راكبي الدراجات ولا يجوز لها التجاوز. السرعة القصوى هي 30 كم / ساعة. غالبًا ما يتم تلوين الطريق باللون الأحمر مع رموز الدراجات للتأكيد على أولوية راكبي الدراجات.', 'images/signs/direction_signs/F111 Fietsstraat.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F105', 'Einde van een voetgangerszone', 'End of pedestrian zone', 'Fin de zone piétonne', 'نهاية منطقة مشاة باستثناء التحميل من 6 إلى 12', 'Begin/einde schoolomgeving.', NULL, NULL, NULL, 'Dit bord geeft aan dat de voetgangerszone eindigt waar beperkingen voor voertuigen golden met uitzondering voor laden en lossen tijdens bepaalde uren. Na dit bord gelden weer de normale verkeersregels.', 'This sign indicates the end of the pedestrian zone where vehicle restrictions applied with exception for loading during specific hours. After this sign, normal traffic rules apply again.', 'Ce panneau indique la fin de la zone piétonne où des restrictions s''appliquaient aux véhicules avec exception pour le chargement pendant des heures spécifiques. Après ce panneau, les règles de circulation normales s''appliquent à nouveau.', 'تشير هذه العلامة إلى نهاية منطقة المشاة التي تطبق عليها قيود المركبات باستثناء التحميل خلال ساعات محددة. بعد هذه الإشارة، يتم تطبيق قواعد المرور العادية مرة أخرى.', 'images/signs/direction_signs/F105 Einde van een voetgangerszone.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F103', 'Begin van een voetgangerszone', 'Start of pedestrian zone', 'Début de zone piétonne', 'منطقة مشاة باستثناء التحميل من 6 إلى 12', 'Begin/einde voetgangerszone.', NULL, NULL, NULL, 'Dit bord geeft aan dat je een voetgangerszone betreedt waar voertuigen de hele dag verboden zijn, behalve tijdens bepaalde uren van 6 tot 12 uur voor laden en lossen. Bezorgvoertuigen en kleine vrachtwagens mogen tijdens deze uren ook binnen.', 'This sign indicates that you are entering a pedestrian zone where vehicles are prohibited all day, except during specific hours from 6 AM to 12 PM for loading and unloading only. Delivery vehicles and small trucks are also allowed during these hours.', 'Ce panneau indique que vous entrez dans une zone piétonne où les véhicules sont interdits toute la journée, sauf pendant des heures spécifiques de 6h à 12h pour le chargement et le déchargement uniquement. Les véhicules de livraison et les petits camions sont également autorisés pendant ces heures.', 'تشير هذه العلامة إلى أنك تدخل منطقة للمشاة يُحظر فيها استخدام المركبات طوال اليوم، باستثناء ساعات محددة من الساعة 6 صباحًا حتى الساعة 12 ظهرًا للتحميل والتفريغ فقط. يُسمح أيضًا بمركبات التوصيل والشاحنات الصغيرة خلال هذه الساعات.', 'images/signs/direction_signs/F103 Begin van een voetgangerszone.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F101c', 'Einde weg voorbehouden voor voetgangers, fietsers, ruiters en landbouwvoertuigen', 'End of path reserved for pedestrians, cyclists, horse riders and agricultural vehicles', 'Fin de chemin réservé aux piétons, cyclistes, cavaliers et véhicules agricoles', 'نهاية المسار للمشاة والدراجات والمركبات الزراعية', 'Einde van de weg voorbehouden voor het verkeer van voetgangers, fietsers en ruiters.', NULL, NULL, NULL, 'Dit bord geeft het einde aan van de weg die was voorbehouden voor voetgangers, fietsers, ruiters en landbouwvoertuigen. Vanaf dit punt gelden de normale verkeersregels weer.', 'This sign indicates the end of the road that was reserved for pedestrians, cyclists, horse riders and agricultural vehicles. From this point, normal traffic rules apply again.', 'Ce panneau indique la fin de la route qui était réservée aux piétons, cyclistes, cavaliers et véhicules agricoles. À partir de ce point, les règles de circulation normales s''appliquent à nouveau.', 'تشير هذه الشاخصة إلى نهاية الطريق الذي كان مخصصاً للمشاة وراكبي الدراجات الهوائية وراكبي الخيل والمركبات الزراعية. ومن هذه النقطة، يتم تطبيق قواعد المرور العادية مرة أخرى.', 'assets/signs/aanwijzingsborden/F101c Einde voorbehouden voor landbouwvoertuigen voetgangers fietsers ruiters en speed pedelecs.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F101b', 'Einde gescheiden pad voor voetgangers en fietsers', 'End of separated path for pedestrians and cyclists', 'Fin du chemin séparé pour piétons et cyclistes', 'نهاية المسار المنفصل للمشاة وراكبي الدراجات', 'Einde van de weg voorbehouden voor het verkeer van voetgangers, fietsers en ruiters.', NULL, NULL, NULL, 'Dit bord geeft het einde aan van het gescheiden pad voor voetgangers en fietsers. Vanaf dit punt gelden de normale verkeersregels weer en delen voetgangers en fietsers dezelfde weg.', 'This sign indicates the end of the separated path for pedestrians and cyclists. From this point, normal traffic rules apply again and pedestrians and cyclists share the same road.', 'Ce panneau indique la fin du chemin séparé pour piétons et cyclistes. À partir de ce point, les règles de circulation normales s''appliquent à nouveau et les piétons et cyclistes partagent la même route.', 'تشير هذه العلامة إلى نهاية المسار المنفصل للمشاة وراكبي الدراجات. ومن هذه النقطة، يتم تطبيق قواعد المرور العادية مرة أخرى ويتشارك المشاة وراكبي الدراجات في نفس الطريق.', 'assets/signs/aanwijzingsborden/F101b Einde deel van de openbare weg voorbehouden voor fietsers en voetgangers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F101a', 'Einde weg voorbehouden voor voetgangers, fietsers en ruiters', 'End of path reserved for pedestrians, cyclists and horse riders', 'Fin de chemin réservé aux piétons, cyclistes et cavaliers', 'نهاية المسار المشترك للمشاة والدراجات والخيالة', 'Einde van de weg voorbehouden voor het verkeer van voetgangers, fietsers en ruiters.', NULL, NULL, NULL, 'Dit bord geeft het einde aan van de weg die was voorbehouden voor voetgangers, fietsers en ruiters. Vanaf dit punt gelden de normale verkeersregels weer voor alle voertuigen.', 'This sign indicates the end of the road that was reserved for pedestrians, cyclists and horse riders. From this point, normal traffic rules apply again for all vehicles.', 'Ce panneau indique la fin de la route qui était réservée aux piétons, cyclistes et cavaliers. À partir de ce point, les règles de circulation normales s''appliquent à nouveau pour tous les véhicules.', 'تشير هذه العلامة إلى نهاية الطريق الذي كان مخصصاً للمشاة وراكبي الدراجات الهوائية وراكبي الخيل. ومن هذه النقطة، تنطبق قواعد المرور العادية مرة أخرى على جميع المركبات.', 'assets/signs/aanwijzingsborden/F101a Einde voorbehouden voor voetgangers fietsers ruiters en speed pedelecs.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F99c', 'Weg voorbehouden voor voetgangers, fietsers, ruiters en landbouwvoertuigen', 'Path reserved for pedestrians, cyclists, horse riders and agricultural vehicles', 'Chemin réservé aux piétons, cyclistes, cavaliers et véhicules agricoles', 'مسار مشترك للمشاة والدراجات والمركبات الزراعية', NULL, NULL, NULL, NULL, 'Dit bord geeft aan dat deze weg uitsluitend is voorbehouden voor voetgangers, fietsers, ruiters en landbouwvoertuigen. Alle andere voertuigen zijn niet toegestaan op deze weg.', 'This sign indicates that this road is exclusively reserved for pedestrians, cyclists, horse riders and agricultural vehicles. All other vehicles are not allowed on this road.', 'Ce panneau indique que cette route est exclusivement réservée aux piétons, cyclistes, cavaliers et véhicules agricoles. Tous les autres véhicules ne sont pas autorisés sur cette route.', 'تشير هذه الإشارة إلى أن هذا الطريق مخصص فقط للمشاة وراكبي الدراجات الهوائية وراكبي الخيل والمركبات الزراعية. لا يُسمح لجميع المركبات الأخرى بالسير على هذا الطريق.', 'assets/signs/aanwijzingsborden/F99c Voorbehouden voor landbouwvoertuigen voetgangers fietsers ruiters en speed pedelecs.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F99b', 'Gescheiden pad voor voetgangers en fietsers', 'Separated path for pedestrians and cyclists', 'Chemin séparé pour piétons et cyclistes', 'مسار منفصل للمشاة وراكبي الدراجات', NULL, NULL, NULL, NULL, 'Dit bord geeft aan dat de weg is verdeeld in twee gescheiden rijstroken: één voor voetgangers en één voor fietsers. Elke gebruiker moet op zijn eigen strook blijven en mag de strook van de ander niet gebruiken. De stroken zijn meestal gescheiden door een lijn of een eenvoudige barrière voor de veiligheid.', 'This sign indicates that the road is divided into two separate lanes: one for pedestrians and one for cyclists. Each user must stay in their own lane and may not use the other''s lane. The lanes are usually separated by a line or simple barrier for safety.', 'Ce panneau indique que la route est divisée en deux voies séparées : une pour les piétons et une pour les cyclistes. Chaque usager doit rester dans sa propre voie et ne peut pas utiliser celle de l''autre. Les voies sont généralement séparées par une ligne ou une barrière simple pour la sécurité.', 'تشير هذه الإشارة إلى أن الطريق مقسم إلى مسارين منفصلين: مسار للمشاة وآخر لراكبي الدراجات. يجب على كل مستخدم البقاء في المسار الخاص به ولا يجوز له استخدام المسار الخاص بالآخر. عادة ما يتم فصل الممرات بخط أو حاجز بسيط للسلامة.', 'assets/signs/aanwijzingsborden/F99b Deel van de openbare weg voorbehouden voor fietsers en voetgangers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F99a', 'Weg voorbehouden voor voetgangers, fietsers en ruiters', 'Path reserved for pedestrians, cyclists and horse riders', 'Chemin réservé aux piétons, cyclistes et cavaliers', 'مسار مشترك للمشاة والدراجات والخيالة', 'Weg voorbehouden voor het verkeer van voetgangers, fietsers en ruiters.', NULL, NULL, NULL, 'Dit bord geeft aan dat de weg uitsluitend is bestemd voor voetgangers, fietsers en ruiters. Alle andere voertuigen zijn verboden op deze weg.', 'This sign indicates that the road is exclusively for pedestrians, cyclists and horse riders. All other vehicles are prohibited on this road.', 'Ce panneau indique que la route est exclusivement réservée aux piétons, cyclistes et cavaliers. Tous les autres véhicules sont interdits sur cette route.', 'تشير هذه الإشارة إلى أن الطريق مخصص للمشاة وراكبي الدراجات الهوائية وراكبي الخيل فقط. جميع المركبات الأخرى محظورة على هذا الطريق.', 'assets/signs/aanwijzingsborden/F99a Voorbehouden voor voetgangers fietsers ruiters en speed pedelecs.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F97-v1', 'Rijstrook versmalling links', 'Lane narrowing on the left', 'Rétrécissement de voie à gauche', 'تضيق على الطريق من جهة اليسار', 'Verkeersbord dat een versmalling aanduidt die de omvang van een rijstrook heeft.', NULL, NULL, NULL, 'Dit bord geeft aan dat de weg smaller wordt aan de linkerkant. Dit betekent dat bestuurders op de linkerrijstrook veilig moeten invoegen in de andere rijstroken omdat zij geen voorrang hebben. Dit bord wordt meestal geplaatst voor wegwerkzaamheden, tunnelingangen, bruggen of verkeerslichten.', 'This sign indicates that the road will narrow on the left side. This means drivers in the left lane must safely merge into other lanes as they do not have priority. This sign is usually placed before road works, tunnel entrances, bridges or traffic lights.', 'Ce panneau indique que la route va se rétrécir du côté gauche. Cela signifie que les conducteurs sur la voie de gauche doivent s''insérer en toute sécurité dans les autres voies car ils n''ont pas la priorité. Ce panneau est généralement placé avant des travaux routiers, des entrées de tunnels, des ponts ou des feux de circulation.', 'تشير هذه العلامة إلى أن الطريق سوف يضيق على الجانب الأيسر. وهذا يعني أنه يجب على السائقين الموجودين في المسار الأيسر الاندماج بأمان في الممرات الأخرى حيث ليس لديهم الأولوية. توضع هذه الإشارة عادة قبل أعمال الطرق أو مداخل الأنفاق أو الجسور أو إشارات المرور.', 'assets/signs/aanwijzingsborden/F97 Rijstrook versmalling.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F50bis', 'Opgepast bij richtingsverandering - voetgangers rechts', 'Caution when changing direction - pedestrians on the right', 'Attention au changement de direction - piétons à droite', 'تحذير من عبور المشاة على يمين الطريق', NULL, NULL, NULL, NULL, 'Dit verkeersbord waarschuwt dat voetgangers de weg kunnen oversteken vanaf rechts, vooral bij kruispunten of fietspaden. Wees voorzichtig, verminder uw snelheid en geef voorrang aan voetgangers.', 'This traffic sign warns that pedestrians may cross the road from the right, especially at intersections or cycle paths. Be careful, reduce your speed, and give priority to pedestrians.', 'Ce panneau de signalisation avertit que les piétons peuvent traverser la route par la droite, notamment aux intersections ou pistes cyclables. Soyez prudent, réduisez votre vitesse et donnez la priorité aux piétons.', 'تحذر هذه العلامة المرورية من إمكانية عبور المشاة للطريق من اليمين، خاصة عند التقاطعات أو مسارات الدراجات. كن حذرا، وخفف من سرعتك، وأعطي الأولوية للمشاة.', 'assets/signs/aanwijzingsborden/F50bis Opgepast als je van richting verandert voetgangers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F50b', 'Opgepast bij richtingsverandering - fietsers rechts', 'Caution when changing direction - cyclists on the right', 'Attention au changement de direction - cyclistes à droite', 'تحذير من عبور الدراجات على يمين الطريق', 'Oversteekplaats voor fietsers en bestuurders van tweewielige bromfietsen.', 'Cyclist crossing.', 'Passage pour cyclistes.', 'ممر لراكبي الدراجات.', 'Dit verkeersbord waarschuwt voor een fietspad aan de rechterkant van de weg. Verminder uw snelheid, geef voorrang aan fietsers en let op fietsverkeer.', 'This traffic sign warns of a bicycle path on the right side of the road. Reduce your speed, give priority to cyclists, and watch for bicycle traffic.', 'Ce panneau de signalisation avertit de la présence d''une piste cyclable sur le côté droit de la route. Réduisez votre vitesse, donnez la priorité aux cyclistes et faites attention à la circulation des vélos.', 'تحذر هذه العلامة المرورية من وجود مسار للدراجات على الجانب الأيمن من الطريق. خفف من سرعتك، وأعطي الأولوية لراكبي الدراجات، وانتبه لحركة مرور الدراجات.', 'assets/signs/aanwijzingsborden/F50bis Opgepast als je van richting verandert fietsers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F50', 'Oversteekplaats voor fietsers', 'Crossing for cyclists', 'Passage pour cyclistes', 'ممر مخصص لعبور راكبي الدراجات الهوائية', 'Oversteekplaats voor fietsers en bestuurders van tweewielige bromfietsen.', 'Cyclist crossing.', 'Passage pour cyclistes.', 'ممر لراكبي الدراجات.', 'Dit bord geeft een speciale oversteekplaats voor fietsers aan. Deze bevindt zich vaak bij kruispunten of in stadscentra. Bestuurders moeten stoppen en voorrang verlenen aan fietsers die deze oversteekplaats gebruiken, net zoals bij voetgangersoversteekplaatsen.', 'This sign indicates a special crossing for cyclists. It is often located at intersections or in city centers. Drivers must stop and give priority to cyclists using this crossing, just like at pedestrian crossings.', 'Ce panneau indique un passage spécial pour les cyclistes. Il se trouve souvent aux carrefours ou dans les centres-villes. Les conducteurs doivent s''arrêter et donner la priorité aux cyclistes qui utilisent ce passage, tout comme aux passages piétons.', 'تشير هذه العلامة إلى معبر خاص لراكبي الدراجات. غالبًا ما يقع عند التقاطعات أو في مراكز المدن. يجب على السائقين التوقف وإعطاء الأولوية لراكبي الدراجات الذين يستخدمون هذا المعبر، كما هو الحال عند معابر المشاة.', 'images/signs/direction_signs/F50 Oversteekplaats voor fietsers en bromfietsers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F49', 'Oversteekplaats voor voetgangers', 'Pedestrian crossing', 'Passage pour piétons', 'ممر مخصص لعبور المشاة', 'Oversteekplaats voor voetgangers.', 'Pedestrian crossing.', 'Passage pour piétons.', 'ممر للمشاة.', 'Dit bord geeft een oversteekplaats aan die uitsluitend is bestemd voor voetgangers. Het wordt vaak geplaatst bij scholen of in woonstraten. Bestuurders moeten onmiddellijk stoppen en voorrang verlenen aan voetgangers die de oversteekplaats naderen, om hun veiligheid te waarborgen.', 'This sign indicates a crossing exclusively for pedestrians. It is often placed near schools or in residential streets. Drivers must stop immediately and give priority to pedestrians approaching the crossing to ensure their safety.', 'Ce panneau indique un passage exclusivement réservé aux piétons. Il est souvent placé près des écoles ou dans les rues résidentielles. Les conducteurs doivent s''arrêter immédiatement et donner la priorité aux piétons qui s''approchent du passage pour assurer leur sécurité.', 'تشير هذه الإشارة إلى وجود معبر مخصص للمشاة فقط. غالبًا ما يتم وضعه بالقرب من المدارس أو في الشوارع السكنية. يجب على السائقين التوقف فوراً وإعطاء الأولوية للمشاة الذين يقتربون من المعبر لضمان سلامتهم.', 'images/signs/direction_signs/F49 Oversteekplaats voor voetgangers.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F47', 'Einde van de werken.', 'End van de Road works.', 'Fin van de Travaux.', 'أعمال نهاية فان دي رود.', NULL, NULL, NULL, NULL, 'Einde van de werken.', 'End van de Road works.', 'Fin van de Travaux.', 'أعمال نهاية فان دي رود.', 'images/signs/direction_signs/F47 Einde van de werken.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F45b-v2', 'Doodlopende weg, uitgezonderd voetgangers en fietsers', 'Dead end except for pedestrians and cyclists', 'Impasse sauf piétons et cyclistes', 'طريق مسدود باستثناء المشاة وراكبي الدراجات', 'Doodlopende weg.', 'Dead end.', 'Voie sans issue.', 'طريق مسدود.', 'Doodlopende weg, uitgezonderd voetgangers en fietsers.', 'Dead end except for pedestrians and cyclists.', 'Impasse sauf piétons et cyclistes.', 'طريق مسدود باستثناء المشاة وراكبي الدراجات.', 'assets/signs/aanwijzingsborden/F45b Doodlopende weg (rechts_links).png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F45', 'Doodlopende weg', 'Dead end road', 'Voie sans issue', 'طريق مغلق', 'Doodlopende weg.', 'Dead end.', 'Voie sans issue.', 'طريق مسدود.', 'Dit verkeersbord geeft aan dat de weg of straat doodloopt en je niet verder kunt rijden, maar je mag wel deze weg inrijden.', 'This traffic sign indicates that the road or street is a dead end and you cannot continue driving, but you are allowed to enter this road.', 'Ce panneau de signalisation indique que la route ou la rue est sans issue et que vous ne pouvez pas continuer à conduire, mais vous êtes autorisé à entrer dans cette route.', 'تشير هذه العلامة المرورية إلى أن الطريق أو الشارع هو طريق مسدود ولا يمكنك مواصلة القيادة، ولكن مسموح لك الدخول إلى هذا الطريق.', 'images/signs/direction_signs/F45 Doodlopende weg.png', TRUE, NOW(), NOW()),
    ((SELECT id FROM categories WHERE code='F'), 'F43', 'Gemeentegrens', 'Start of residential area', 'Limite de commune', 'بداية منطقة سكنية', NULL, NULL, NULL, NULL, 'Dit bord geeft de grens van een gemeente aan en wordt vaak vergezeld door snelheidswijzigingen. Het heeft geen speciale verkeersregels, maar dient als aanduiding dat je een bepaalde stad of gemeente binnenrijdt.', 'This sign is used to indicate entry into a residential area, usually accompanied by speed changes. It has no special rules, just consider it a notification that you have arrived at this city or another.', 'Ce panneau est utilisé pour indiquer l''entrée dans une zone résidentielle, généralement accompagnée de changements de vitesse. Il n''a pas de règles particulières, considérez-le simplement comme une notification que vous êtes arrivé dans cette ville ou une autre.', 'تُستخدم هذه العلامة للإشارة إلى الدخول إلى منطقة سكنية، وعادةً ما يكون مصحوبًا بتغييرات في السرعة. ليس لها قواعد خاصة، فقط اعتبرها إشعارًا بوصولك إلى هذه المدينة أو تلك.', 'images/signs/direction_signs/F43 Gemeentegrens.png', TRUE, NOW(), NOW())
ON DUPLICATE KEY UPDATE
    name_nl=VALUES(name_nl), name_en=VALUES(name_en), name_fr=VALUES(name_fr), name_ar=VALUES(name_ar),
    description_nl=VALUES(description_nl), description_en=VALUES(description_en),
    description_fr=VALUES(description_fr), description_ar=VALUES(description_ar),
    long_description_nl=VALUES(long_description_nl), long_description_en=VALUES(long_description_en),
    long_description_fr=VALUES(long_description_fr), long_description_ar=VALUES(long_description_ar),
    image_url=VALUES(image_url), is_active=TRUE, updated_at=NOW();

